// Erzeugt von scripts/build-data.mjs – nicht von Hand bearbeiten (Quelle: data/src).
window.MEDI_DETAILS = Object.assign(window.MEDI_DETAILS || {}, {"paclitaxel":{"wirkmechanismus":"Hemmt die Zellteilung, indem es das Zellskelett der Krebszellen «einfriert». Paclitaxel bindet an die β-Tubulin-Untereinheit der Mikrotubuli und stabilisiert sie, sodass sie nicht mehr abgebaut werden können. Die Mitosespindel verliert ihre Funktion, die Zellen bleiben in der G2/M-Phase stehen und sterben ab. Bei Abraxane ist Paclitaxel an Albumin-Nanopartikel gebunden und kommt ohne das allergieauslösende Lösungsmittel Macrogolglycerolricinoleat (Rizinusöl-Derivat) aus.","nebenwirkungen":{"sehrHaeufig":["Knochenmarkhemmung: Neutropenie, Anämie, Thrombozytopenie, Blutungen","Infektionen (v. a. Harn- und obere Atemwege)","Periphere Neuropathie (Kribbeln, Taubheit in Händen und Füssen)","Leichte Überempfindlichkeitsreaktionen (Hautrötung, Ausschlag)","Blutdruckabfall","Übelkeit, Erbrechen, Durchfall, Mukositis (Schleimhautentzündung)","Haarausfall","Gelenk- und Muskelschmerzen"],"haeufig":["Bradykardie (langsamer Puls)","Vorübergehende Nagel- und Hautveränderungen","Reaktionen an der Injektionsstelle","Erhöhte Leberwerte (AST, alkalische Phosphatase)"],"gelegentlich":["Schwere Überempfindlichkeitsreaktionen (Blutdruckabfall, Atemnot, Angioödem, generalisierte Nesselsucht)","Septischer Schock","Herzrhythmusstörungen, AV-Block, Synkope, Herzinfarkt, Kardiomyopathie","Bluthochdruck, Thrombose, Thrombophlebitis","Stark erhöhtes Bilirubin"],"selten":["Anaphylaxie (schwere allergische Reaktion)","Pneumonie, Sepsis, febrile Neutropenie","Herzschwäche","Interstitielle Pneumonie, Lungenfibrose, Lungenembolie","Darmverschluss, Darmperforation, ischämische Kolitis, Pankreatitis","Motorische Neuropathie (Muskelschwäche)"],"sehrSelten":["Akute myeloische Leukämie, myelodysplastisches Syndrom","Autonome Neuropathie (Darmlähmung, Blutdruckabfall beim Aufstehen), Krampfanfälle, Enzephalopathie","Sehnerv- und Sehstörungen, Hörverlust, Tinnitus","Vorhofflimmern","Lebernekrose, hepatische Enzephalopathie","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, Erythema multiforme"],"unbekannt":["Tumorlyse-Syndrom","Makulaödem (Netzhautschwellung), Lichtblitze","Sklerodermie-artige Hautverhärtung","Kutaner Lupus erythematodes"]},"schwangerschaft":"Im Tierversuch fruchtschädigend; in der Schwangerschaft nur bei zwingender Indikation. Frauen und Männer müssen während und je nach Präparat mehrere Monate nach der Behandlung sicher verhüten.","stillzeit":"Kontraindiziert – während der Behandlung nicht stillen.","hinweise":["Vor konventionellem Paclitaxel ist eine Vorbehandlung mit Kortikosteroid und Antihistaminika nötig; Abraxane braucht keine und ist mit konventionellem Paclitaxel nicht austauschbar.","Die konventionelle Infusionslösung enthält Alkohol: nach der Infusion nicht Auto fahren, bis die Wirkung abgeklungen ist.","Kribbeln oder Taubheit in Händen und Füssen früh melden – eine Dosisanpassung kann bleibende Nervenschäden verhindern.","Blutbild vor jedem Zyklus; bei Fieber sofort ärztliche Hilfe holen."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung","Pulver zur Herstellung einer Infusionssuspension (an Albumin gebunden)"]},"palbociclib":{"wirkmechanismus":"Bremst die Teilung hormonempfindlicher Brustkrebszellen. Palbociclib hemmt selektiv die Cyclin-abhängigen Kinasen 4 und 6 (CDK4/6), die zusammen mit Cyclin D das Retinoblastom-Protein (Rb) phosphorylieren. Ohne diese Phosphorylierung bleibt der Zellzyklus in der G1-Phase stehen, und die Zelle kann die DNA-Synthese nicht beginnen. Zusammen mit einer antihormonellen Therapie verstärkt sich die wachstumshemmende Wirkung.","nebenwirkungen":{"sehrHaeufig":["Neutropenie, Leukopenie, Anämie, Thrombozytopenie","Infektionen","Stomatitis, Übelkeit, Durchfall, Erbrechen","Appetitlosigkeit","Haarausfall, Hautausschlag, trockene Haut","Müdigkeit, Schwäche (Asthenie), Fieber"],"haeufig":["Febrile Neutropenie","Geschmacksstörungen","Verschwommenes Sehen, vermehrter Tränenfluss, trockene Augen","Nasenbluten","Interstitielle Lungenerkrankung, Pneumonitis","Erhöhte Leberwerte (ALT, AST)"]},"schwangerschaft":"Nicht anwenden (im Tierversuch fruchtschädigend). Frauen und Männer mit Partnerin im gebärfähigen Alter müssen während und noch einige Wochen nach der Behandlung sicher verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Einnahme an 21 Tagen, danach 7 Tage Pause; täglich etwa zur gleichen Zeit. Kapseln mit einer Mahlzeit, Tabletten mit oder ohne Mahlzeit unzerkaut schlucken.","Grapefruit und Grapefruitsaft meiden; Johanniskraut ist nicht erlaubt.","Das Blutbild wird regelmässig kontrolliert; Fieber oder Infektzeichen sofort melden."],"darreichung":["Kapseln","Filmtabletten"]},"paliperidon":{"wirkmechanismus":"Dämpft Wahn und Halluzinationen, indem es die Wirkung von Dopamin und Serotonin im Gehirn hemmt. Paliperidon (9-Hydroxy-Risperidon) ist der aktive Metabolit von Risperidon und blockiert Dopamin-D2- und Serotonin-5-HT2A-Rezeptoren sowie Alpha-1- und Histamin-H1-Rezeptoren. Es wird kaum in der Leber abgebaut und überwiegend unverändert über die Niere ausgeschieden. Das Depot (Paliperidonpalmitat) gibt den Wirkstoff über Wochen bis Monate gleichmässig ab.","nebenwirkungen":{"sehrHaeufig":["Schlaflosigkeit","Kopfschmerzen"],"haeufig":["Parkinsonismus, Sitzunruhe (Akathisie), Dystonie, Dyskinesien, Zittern","Schläfrigkeit, Schwindel","Erhöhtes Prolaktin, Gewichtszunahme, erhöhter Blutzucker","Angst, Unruhe, Depression","Herzrasen, Bluthochdruck","Übelkeit, Erbrechen, Verstopfung, Durchfall, Bauchschmerzen","Atemwegs- und Harnwegsinfekte","Reaktionen an der Injektionsstelle, Schwäche, Fieber"],"gelegentlich":["QT-Verlängerung, Bradykardie, AV-Block","Orthostatische Hypotonie (Blutdruckabfall beim Aufstehen), Ohnmacht","Krampfanfälle, Spätdyskinesien","Diabetes","Milchfluss, Ausbleiben der Regel, sexuelle Funktionsstörungen","Neutropenie, Anämie"],"selten":["Malignes neuroleptisches Syndrom","Venöse Thromboembolie","Darmverschluss, Pankreatitis","Priapismus","Floppy-Iris-Syndrom bei Operation des Grauen Stars"],"unbekannt":["Agranulozytose","Anaphylaxie, Angioödem","Entzugssymptome und Bewegungsstörungen beim Neugeborenen"]},"schwangerschaft":"Begrenzte Erfahrungen; nur anwenden, wenn der Nutzen das Risiko überwiegt. Nach Anwendung im letzten Drittel sind beim Neugeborenen Bewegungsstörungen und Entzugssymptome möglich; das Depot wirkt noch Monate nach.","stillzeit":"Paliperidon geht in die Muttermilch über. Während der Behandlung nicht stillen.","hinweise":["Retardtabletten morgens ganz schlucken; die leere Tablettenhülle kann im Stuhl erscheinen – das ist normal.","Termine für die Depotspritze einhalten; eine verpasste Injektion ärztlich nachholen lassen.","Gewicht, Blutzucker und Blutfette regelmässig kontrollieren.","Langsam aufstehen; Alkohol meiden, Fahrtüchtigkeit kann beeinträchtigt sein."],"darreichung":["Retardtabletten","Depot-Injektionssuspension"]},"palonosetron":{"wirkmechanismus":"Verhindert den durch Chemotherapie ausgelösten Brechreiz über mehrere Tage. Palonosetron blockiert selektiv und mit sehr hoher Bindungsstärke die Serotonin-5-HT3-Rezeptoren an den Vagusnerv-Endigungen im Darm und in der Brechreizzone des Hirnstamms. Im Unterschied zu älteren Setronen bindet es zusätzlich allosterisch, führt zur Internalisierung der Rezeptoren und hat eine lange Halbwertszeit von rund 40 Stunden; deshalb genügt meist eine Einzeldosis pro Chemotherapie-Zyklus.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Schwindel","Obstipation (Verstopfung)","Durchfall"],"gelegentlich":["Schlaflosigkeit oder Schläfrigkeit, Angst","Missempfindungen (Kribbeln), periphere Nervenstörungen","Herzrhythmusstörungen (Herzrasen, langsamer Puls, Extrasystolen), QT-Verlängerung im EKG","Blutdruckabfall oder Blutdruckanstieg","Bauchschmerzen, Verdauungsbeschwerden, Mundtrockenheit, Blähungen","Elektrolytstörungen (z. B. erhöhtes Kalium, tiefes Calcium), erhöhter Blutzucker","Erhöhte Leberwerte und Bilirubin","Müdigkeit, Schwäche, grippeähnliche Beschwerden"],"sehrSelten":["Anaphylaxie und andere Überempfindlichkeitsreaktionen","Reaktionen an der Injektionsstelle (Brennen, Schmerzen, Rötung)"]},"schwangerschaft":"Keine Erfahrungen beim Menschen; in der Schwangerschaft nur anwenden, wenn es klar notwendig ist.","stillzeit":"Nicht bekannt, ob Palonosetron in die Muttermilch übergeht; während der Behandlung soll nicht gestillt werden.","hinweise":["Wird in der Regel einmalig etwa 30 Minuten vor Beginn der Chemotherapie gespritzt; weitere Gaben innerhalb von 7 Tagen nicht empfohlen.","Verstopfung ist häufig: ausreichend trinken und bei anhaltenden Beschwerden die Behandlungsteams informieren."],"darreichung":["Injektionslösung","Kapseln (Kombination mit Netupitant)"]},"pankreatin":{"wirkmechanismus":"Ersetzt die Verdauungsenzyme, die eine geschwächte Bauchspeicheldrüse nicht mehr ausreichend bildet. Pankreatin wird aus der Bauchspeicheldrüse von Schweinen gewonnen und enthält Lipase (spaltet Fett), Amylase (spaltet Stärke) und Proteasen (spalten Eiweiss). Magensaftresistent überzogene Mikropellets schützen die Enzyme vor der Magensäure, mischen sich mit dem Speisebrei und geben die Enzyme erst im Zwölffingerdarm frei. Dadurch bessern sich Fettstühle, Blähungen und Gewichtsverlust, und fettlösliche Vitamine werden besser aufgenommen; die Enzyme wirken nur im Darm und werden nicht ins Blut aufgenommen.","nebenwirkungen":{"sehrHaeufig":["Bauchschmerzen"],"haeufig":["Übelkeit, Erbrechen","Verstopfung (Obstipation)","Blähbauch","Durchfall"],"gelegentlich":["Hautausschlag"],"unbekannt":["Fibrosierende Kolonopathie (Verengungen am Übergang Dünn-/Dickdarm und im Dickdarm), v. a. bei hohen Dosen und zystischer Fibrose","Überempfindlichkeitsreaktionen bis Anaphylaxie","Juckreiz, Nesselsucht"]},"schwangerschaft":"Die Enzyme werden nicht aufgenommen; bei Bedarf kann Pankreatin in der Schwangerschaft angewendet werden, um eine ausreichende Ernährung sicherzustellen.","stillzeit":"Anwendung in der Stillzeit möglich.","hinweise":["Zu jeder Mahlzeit und Zwischenmahlzeit einnehmen; Kapseln unzerkaut mit Flüssigkeit schlucken.","Bei Schluckproblemen Kapsel öffnen und die Pellets mit einer sauren, weichen Speise (z. B. Apfelmus) einnehmen – nicht zerkauen und nicht in heisse Speisen mischen (Reizung der Mundschleimhaut, Wirkungsverlust).","Ausreichend trinken, besonders bei zystischer Fibrose (beugt Verstopfung vor).","Enthält Eiweiss vom Schwein."],"darreichung":["Kapseln mit magensaftresistenten Mikropellets"]},"pantoprazol":{"wirkmechanismus":"Senkt die Bildung von Magensäure stark und anhaltend. Pantoprazol wird in den sauren Belegzellen der Magenschleimhaut in seine aktive Form umgewandelt und blockiert dort irreversibel die Protonenpumpe (H+/K+-ATPase), den letzten Schritt der Säurebildung. Da neue Pumpen erst nachgebildet werden müssen, hält die Wirkung länger an, als der Wirkstoff im Blut vorhanden ist. Pantoprazol wird über CYP2C19 und CYP3A4 abgebaut, hemmt diese Enzyme aber kaum und hat daher weniger Wechselwirkungen als Omeprazol.","nebenwirkungen":{"haeufig":["Gutartige Drüsenpolypen im Magen (Fundusdrüsenpolypen)"],"gelegentlich":["Kopfschmerzen, Schwindel","Schlafstörungen","Durchfall, Verstopfung, Blähungen, Bauchschmerzen","Übelkeit, Erbrechen, Mundtrockenheit","Erhöhte Leberwerte","Hautausschlag, Juckreiz","Knochenbrüche (Hüfte, Handgelenk, Wirbelsäule)","Schwäche, Müdigkeit, Unwohlsein"],"selten":["Agranulozytose (starker Mangel an weissen Blutkörperchen)","Überempfindlichkeitsreaktionen bis zum anaphylaktischen Schock, Angioödem, Nesselsucht","Depression, Geschmacksstörungen, Sehstörungen","Erhöhte Blutfette, Gewichtsveränderungen","Gelenk- und Muskelschmerzen","Gynäkomastie (Brustvergrösserung beim Mann), Fieber, Wassereinlagerungen"],"sehrSelten":["Thrombozytopenie, Leukopenie, Panzytopenie (Mangel an Blutzellen)","Desorientierung"],"unbekannt":["Hyponatriämie (Natriummangel) und Hypomagnesiämie (Magnesiummangel)","Halluzinationen, Verwirrtheit","Mikroskopische Kolitis","Leberzellschädigung, Gelbsucht, Leberversagen","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, Erythema multiforme, DRESS","Subakuter kutaner Lupus erythematodes, Lichtempfindlichkeit","Tubulointerstitielle Nephritis (Nierenentzündung)","Muskelkrämpfe"]},"schwangerschaft":"Erfahrungen sind begrenzt; vorsichtshalber in der Schwangerschaft nur nach ärztlicher Abwägung anwenden.","stillzeit":"Pantoprazol geht in die Muttermilch über; nur nach ärztlicher Nutzen-Risiko-Abwägung anwenden.","hinweise":["Tablette unzerkaut mit etwas Wasser etwa 1 Stunde vor einer Mahlzeit, meist vor dem Frühstück, einnehmen.","Rezeptfreie Selbstbehandlung (20 mg) höchstens 4 Wochen; tritt nach 2 Wochen keine Besserung ein, ärztlich abklären.","Nach längerer Einnahme nicht abrupt absetzen: vorübergehend vermehrte Säurebildung (Rebound) möglich.","Bei Langzeitbehandlung regelmässig die Notwendigkeit sowie Magnesium und Vitamin B12 überprüfen lassen."],"darreichung":["Magensaftresistente Tabletten","Pulver zur Herstellung einer Injektionslösung"]},"paracetamol":{"wirkmechanismus":"Lindert Schmerzen und senkt Fieber, ohne Magen und Blutplättchen wesentlich zu beeinflussen. Paracetamol hemmt vorwiegend im Zentralnervensystem die Bildung von Prostaglandinen und beeinflusst schmerzhemmende Bahnen, unter anderem über serotonerge Mechanismen; entzündungshemmend wirkt es kaum. In der Leber entsteht in kleinen Mengen das giftige Abbauprodukt NAPQI, das normalerweise durch Glutathion entgiftet wird. Bei Überdosierung oder Glutathionmangel kann es die Leber schwer schädigen; Gegenmittel ist Acetylcystein.","nebenwirkungen":{"selten":["Überempfindlichkeitsreaktionen (Hautausschlag, Nesselsucht)","Erhöhte Leberwerte","Blutdruckabfall, Unwohlsein (Infusion)"],"sehrSelten":["Anaphylaxie (schwere allergische Reaktion), Angioödem","Thrombozytopenie, Leukopenie, Agranulozytose (Blutbildveränderungen)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, AGEP)","Bronchospasmus bei Analgetika-Asthma"],"unbekannt":["Leberschaden bis Leberversagen bei Überdosierung oder Risikofaktoren","Metabolische Azidose mit hoher Anionenlücke bei Risikofaktoren","Schmerzen oder Brennen an der Infusionsstelle"]},"schwangerschaft":"Gilt als Schmerz- und Fiebermittel der Wahl in der Schwangerschaft; dennoch nur bei Bedarf, in der niedrigsten wirksamen Dosis und so kurz wie möglich einnehmen.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; in üblicher Dosierung ist Stillen möglich.","hinweise":["Höchstdosis beachten: Erwachsene in der Regel höchstens 4 g pro Tag, bei Lebererkrankung, regelmässigem Alkoholkonsum oder Körpergewicht unter 50 kg weniger; Kinder nach Körpergewicht dosieren.","Viele Kombinations-, Grippe- und Erkältungsmittel enthalten ebenfalls Paracetamol – nicht doppelt einnehmen.","Bei Verdacht auf Überdosierung sofort ärztliche Hilfe holen, auch ohne Beschwerden – das Gegenmittel wirkt nur früh.","Ohne ärztlichen Rat nicht länger als 5 Tage gegen Schmerzen bzw. 3 Tage gegen Fieber einnehmen."],"darreichung":["Tabletten","Filmtabletten","Brausetabletten","Schmelztabletten","Sirup","Zäpfchen","Infusionslösung"]},"paracetamol-codein":{"wirkmechanismus":"Kombiniert zwei unterschiedlich wirkende Schmerzmittel, die sich ergänzen. Paracetamol hemmt vor allem im Zentralnervensystem die Bildung von Prostaglandinen und wirkt schmerzlindernd und fiebersenkend. Codein ist eine Vorstufe (Prodrug): Es wird in der Leber durch das Enzym CYP2D6 zu Morphin umgewandelt, das an μ-Opioidrezeptoren die Schmerzweiterleitung hemmt. Bei «ultraschnellen Metabolisierern» entsteht ungewöhnlich viel Morphin, bei «langsamen Metabolisierern» wirkt Codein kaum.","nebenwirkungen":{"haeufig":["Obstipation (Verstopfung)","Übelkeit, Erbrechen","Schläfrigkeit, Benommenheit, Schwindel"],"selten":["Überempfindlichkeitsreaktionen (Hautausschlag, Nesselsucht)","Erhöhte Leberwerte"],"sehrSelten":["Thrombozytopenie, Agranulozytose (Mangel an Blutplättchen bzw. weissen Blutkörperchen)","Anaphylaxie (schwere allergische Reaktion)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, AGEP)","Bronchospasmus bei Analgetika-Asthma"],"unbekannt":["Atemdepression, besonders bei ultraschnellen CYP2D6-Metabolisierern","Kopfschmerzen, Juckreiz","Abhängigkeit bei längerem Gebrauch","Leberschaden bis Leberversagen bei Überdosierung","Metabolische Azidose mit hoher Anionenlücke bei Risikofaktoren"]},"schwangerschaft":"Nur nach ärztlicher Abwägung, so kurz und niedrig dosiert wie möglich. Im letzten Drittel und unter der Geburt meiden (Atemdepression und Entzugssymptome beim Neugeborenen).","stillzeit":"Kontraindiziert: Codein wird zu Morphin umgewandelt, das in die Muttermilch übergeht; bei ultraschnellen Metabolisiererinnen ist eine lebensbedrohliche Vergiftung des Säuglings möglich.","hinweise":["Höchstdosis von Paracetamol nicht überschreiten (Erwachsene in der Regel 4 g pro Tag, bei Risikofaktoren weniger); keine weiteren paracetamolhaltigen Mittel gleichzeitig.","Kein Alkohol; die Fahrtüchtigkeit kann eingeschränkt sein.","Bei Atembeschwerden, starker Schläfrigkeit oder Verwirrtheit sofort ärztliche Hilfe holen.","Nicht länger als nötig einnehmen (Gefahr von Abhängigkeit und Kopfschmerz durch Übergebrauch)."],"darreichung":["Filmtabletten","Brausetabletten"]},"paracetamol-phenylephrin-pheniramin":{"wirkmechanismus":"Lindert Schmerzen und Fieber, lässt die geschwollene Nasenschleimhaut abschwellen und dämpft Niesreiz und Nasenlaufen. Paracetamol wirkt schmerzlindernd und fiebersenkend über eine Hemmung der Prostaglandinbildung vorwiegend im zentralen Nervensystem. Phenylephrin ist ein Alpha-1-Sympathomimetikum, das die Blutgefässe der Nasenschleimhaut verengt. Pheniramin blockiert Histamin-H1-Rezeptoren und wirkt zusätzlich anticholinerg und dämpfend.","nebenwirkungen":{"sehrSelten":["Überempfindlichkeitsreaktionen bis Anaphylaxie (schwere allergische Reaktion)","Thrombozytopenie, Agranulozytose (Mangel an Blutplättchen bzw. weissen Blutkörperchen)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)","Bronchospasmus (Verkrampfung der Atemwege) bei Analgetika-Asthma"],"unbekannt":["Schläfrigkeit, Müdigkeit, Benommenheit","Mundtrockenheit","Herzklopfen, Herzrasen, Blutdruckanstieg","Nervosität, Schlaflosigkeit","Harnverhalt (Schwierigkeiten beim Wasserlassen)","Sehstörungen (Akkommodationsstörungen)","Übelkeit, Magenbeschwerden","Erhöhte Leberwerte; Leberschäden bei Überdosierung"]},"schwangerschaft":"In der Schwangerschaft nicht anwenden; falls nötig, ist Paracetamol allein nach ärztlichem Rat vorzuziehen.","stillzeit":"In der Stillzeit nicht anwenden (Phenylephrin und Pheniramin gehen in die Muttermilch über; Säuglinge reagieren empfindlich).","hinweise":["Nicht gleichzeitig mit anderen paracetamolhaltigen Mitteln einnehmen und die Höchstdosis der Packungsbeilage einhalten – eine Überdosierung kann die Leber schwer schädigen.","Macht müde: kein Alkohol, Vorsicht beim Autofahren und Bedienen von Maschinen.","Ohne ärztlichen Rat nur wenige Tage anwenden; bei hohem oder anhaltendem Fieber ärztlich abklären lassen."],"darreichung":["Pulver zur Herstellung einer Trinklösung (Beutel)"]},"paraffin-dickfluessig":{"wirkmechanismus":"Macht den Stuhl weich und gleitfähig. Dickflüssiges Paraffin ist ein unverdauliches Mineralöl, das im Darm kaum aufgenommen wird. Es umhüllt den Darminhalt, vermindert den Wasserentzug aus dem Stuhl und erleichtert so dessen Passage (Gleitmittel-Laxans).","nebenwirkungen":{"unbekannt":["Austritt von Öl aus dem After, Juckreiz und Reizung im Analbereich","Durchfall und Bauchkrämpfe bei zu hoher Dosis","Verminderte Aufnahme fettlöslicher Vitamine bei Langzeitgebrauch","Lipidpneumonie (Lungenentzündung durch eingeatmetes Öl)","Fremdkörperreaktionen (Paraffinome) in Darmwand und Lymphknoten bei Langzeitgebrauch"]},"schwangerschaft":"Nur kurzfristig und nach ärztlicher Rücksprache anwenden; längerer Gebrauch kann die Aufnahme fettlöslicher Vitamine (v. a. Vitamin K) vermindern.","stillzeit":"Wird kaum ins Blut aufgenommen; eine kurzfristige Anwendung nach Rücksprache ist vertretbar.","hinweise":["Nicht im Liegen und nicht unmittelbar vor dem Schlafengehen einnehmen (Gefahr des Einatmens).","Mindestens 2 Stunden Abstand zu anderen Medikamenten einhalten.","Ohne ärztlichen Rat nur kurzfristig anwenden; ballaststoffreiche Ernährung, ausreichend Flüssigkeit und Bewegung sind die Grundlage."],"darreichung":["Emulsion zum Einnehmen"]},"paromomycin":{"wirkmechanismus":"Tötet Krankheitserreger direkt im Darm ab, da es kaum ins Blut aufgenommen wird. Paromomycin bindet als Aminoglykosid an die 30S-Untereinheit der Ribosomen von Bakterien und Amöben und stört so deren Eiweissbildung. Gegen Amöben im Darminneren wirkt es abtötend; bei schweren Leberkrankheiten vermindert es die Darmbakterien, die Ammoniak bilden.","nebenwirkungen":{"unbekannt":["Übelkeit, Bauchkrämpfe und Durchfall (vor allem bei hohen Dosen)","Malabsorption (gestörte Nährstoffaufnahme) mit Fettstühlen","Hautausschlag, Juckreiz","Pilzinfektionen oder Überwucherung mit resistenten Keimen","Durchfall durch Clostridioides difficile","Nieren- und Gehörschäden bei Aufnahme ins Blut"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Paromomycin wird kaum aufgenommen; Aminoglykoside können bei Aufnahme ins Blut das Gehör des Ungeborenen schädigen.","stillzeit":"Wird kaum ins Blut aufgenommen; Anwendung nach ärztlicher Abwägung.","hinweise":["Kapseln zu den Mahlzeiten einnehmen und die Behandlung wie verordnet zu Ende führen.","Bei längerer Anwendung, vor allem bei Darmgeschwüren, Nierenfunktion und Gehör kontrollieren lassen.","Schweren, anhaltenden oder blutigen Durchfall ärztlich melden."],"darreichung":["Kapseln"]},"paroxetin":{"wirkmechanismus":"Hellt die Stimmung auf und vermindert Angst und Zwänge, indem es die Menge des Botenstoffs Serotonin zwischen den Nervenzellen erhöht. Paroxetin ist ein starker, selektiver Hemmer des Serotonin-Transporters und hat zudem eine schwache anticholinerge Wirkung. Es wird über CYP2D6 abgebaut und hemmt dieses Enzym gleichzeitig stark, was zu zahlreichen Wechselwirkungen führt. Wegen der relativ kurzen Halbwertszeit (etwa 1 Tag) treten beim Absetzen häufiger Absetzsymptome auf als bei anderen SSRI.","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Sexuelle Funktionsstörungen (verminderte Libido, Ejakulations- und Orgasmusstörungen)"],"haeufig":["Erhöhte Cholesterinwerte, verminderter Appetit, Gewichtszunahme","Schläfrigkeit, Schlaflosigkeit, Unruhe, ungewöhnliche Träume","Konzentrationsstörungen, Schwindel, Zittern, Kopfschmerzen","Verschwommenes Sehen","Gähnen","Verstopfung, Durchfall, Erbrechen, Mundtrockenheit","Vermehrtes Schwitzen","Schwäche (Asthenie)"],"gelegentlich":["Ungewöhnliche Blutungen, vor allem der Haut und Schleimhäute (Blutergüsse)","Verwirrtheit, Halluzinationen","Extrapyramidale Störungen (Bewegungsstörungen)","Erweiterte Pupillen, Herzrasen","Blutdruckschwankungen, Blutdruckabfall beim Aufstehen","Hautausschlag, Juckreiz","Harnverhalt, Harninkontinenz"],"selten":["Hyponatriämie (Natriummangel)","Manie, Panikattacken, Angst, Depersonalisation","Akathisie (Bewegungsunruhe), Krampfanfälle, Restless-Legs-Syndrom","Langsamer Puls (Bradykardie)","Erhöhte Leberwerte","Erhöhtes Prolaktin, Milchfluss, Menstruationsstörungen","Gelenk- und Muskelschmerzen"],"sehrSelten":["Thrombozytopenie","Anaphylaxie, Angioödem","Inadäquate ADH-Sekretion (SIADH)","Serotoninsyndrom","Akutes Glaukom","Magen-Darm-Blutungen, Leberentzündung","Schwere Hautreaktionen (Erythema multiforme, Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse), Lichtempfindlichkeit","Priapismus (Dauererektion), Wassereinlagerungen"],"unbekannt":["Suizidgedanken und suizidales Verhalten","Aggressivität, Zähneknirschen (Bruxismus)","Ohrgeräusche (Tinnitus)","Mikroskopische Kolitis (chronischer wässriger Durchfall)","Nachblutungen nach der Geburt"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit: nach Einnahme im ersten Drittel ist das Risiko für Herzfehler etwa verdoppelt (rund 2 statt 1 von 100 Kindern), bei Einnahme bis zur Geburt drohen beim Neugeborenen Anpassungsstörungen und Lungenhochdruck (PPHN). Bei Kinderwunsch die Behandlung ärztlich überprüfen lassen, nicht eigenmächtig absetzen.","stillzeit":"Paroxetin geht nur in geringen Mengen in die Muttermilch über; eine Anwendung ist nach ärztlicher Abwägung möglich.","hinweise":["Einmal täglich morgens zum Frühstück einnehmen; Tablette nicht zerkauen.","Nicht abrupt absetzen: Absetzsymptome (Schwindel, Empfindungsstörungen, Schlafstörungen, Unruhe, Übelkeit) sind häufig – über mehrere Wochen ausschleichen.","Die Wirkung setzt nach 2–4 Wochen ein; zunehmende Unruhe oder Suizidgedanken zu Beginn sofort ärztlich melden.","Kann die Fahrtüchtigkeit beeinträchtigen; Alkohol meiden."],"darreichung":["Filmtabletten"]},"pasireotid":{"wirkmechanismus":"Senkt die Ausschüttung von ACTH und Wachstumshormon aus Tumoren der Hirnanhangsdrüse. Pasireotid ist ein Somatostatin-Analogon, das an mehrere Somatostatin-Rezeptoren bindet, besonders stark an SSTR5. Bei Morbus Cushing hemmt es die ACTH-Bildung des Hypophysentumors und senkt so das Kortisol; bei Akromegalie sinken Wachstumshormon und IGF-1. Durch Hemmung von Insulin und Darmhormonen (Inkretinen) steigt häufig der Blutzucker.","nebenwirkungen":{"sehrHaeufig":["Hyperglykämie (erhöhter Blutzucker), Diabetes mellitus","Erhöhter HbA1c-Wert","Durchfall, Übelkeit, Bauchschmerzen","Gallensteine","Reaktionen an der Injektionsstelle","Müdigkeit"],"haeufig":["Kopfschmerzen, Schwindel","Sinusbradykardie (langsamer Puls), QT-Verlängerung","Niedriger Blutdruck","Nebennierenrinden-Insuffizienz (Kortisolmangel)","Erbrechen, Appetitlosigkeit","Erhöhte Leber- und Bauchspeicheldrüsenwerte","Haarausfall, Juckreiz","Muskel- und Gelenkschmerzen"],"unbekannt":["Diabetische Ketoazidose"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit. Weil die Fruchtbarkeit nach Senkung des Kortisols zurückkehren kann, Verhütung besprechen.","stillzeit":"Stillen wird während der Behandlung nicht empfohlen.","hinweise":["Vor Beginn und regelmässig Blutzucker, HbA1c, EKG, Leberwerte und Gallenblase (Ultraschall) kontrollieren.","Zeichen eines Kortisolmangels (Schwäche, Müdigkeit, Übelkeit, Erbrechen, Schwindel) sofort melden.","Bei Diabetes kann eine Anpassung oder Intensivierung der Blutzuckertherapie nötig sein."],"darreichung":["Injektionslösung (Ampullen)","Pulver und Lösungsmittel zur Herstellung einer Depot-Injektionssuspension"]},"pegfilgrastim":{"wirkmechanismus":"Regt das Knochenmark an, mehr infektabwehrende weisse Blutkörperchen (neutrophile Granulozyten) zu bilden. Pegfilgrastim ist Filgrastim (gentechnisch hergestellter humaner G-CSF), an das ein Polyethylenglykol-Molekül gekoppelt ist. Dadurch wird es kaum über die Niere ausgeschieden, sondern vor allem über die Neutrophilen selbst abgebaut und wirkt viel länger – eine Injektion pro Chemotherapie-Zyklus genügt.","nebenwirkungen":{"sehrHaeufig":["Knochenschmerzen","Kopfschmerzen","Übelkeit"],"haeufig":["Thrombozytopenie (Mangel an Blutplättchen)","Leukozytose (stark erhöhte weisse Blutkörperchen)","Muskel- und Gelenkschmerzen, Rücken- und Gliederschmerzen","Schmerzen an der Einstichstelle","Brustschmerzen (nicht vom Herzen)"],"gelegentlich":["Milzvergrösserung und Milzriss (Milzruptur)","Sichelzellkrisen","Überempfindlichkeitsreaktionen bis Anaphylaxie (schwere allergische Reaktion)","Kapillarlecksyndrom","ARDS (akutes Lungenversagen), Lungeninfiltrate, Bluthusten","Sweet-Syndrom und Hautvaskulitis","Glomerulonephritis (Nierenentzündung)","Erhöhte Harnsäure, LDH und alkalische Phosphatase"],"selten":["Aortitis (Entzündung der Hauptschlagader)","Lungenblutung","Stevens-Johnson-Syndrom (schwere Hautreaktion)"],"unbekannt":["Myelodysplastisches Syndrom oder akute myeloische Leukämie (bei Brust- und Lungenkrebspatienten beschrieben)"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; während der Schwangerschaft nicht empfohlen, ausser nach strenger ärztlicher Abwägung.","stillzeit":"Ein Übergang in die Muttermilch ist nicht auszuschliessen; Entscheid über Stillen oder Therapie ärztlich abwägen.","hinweise":["Bei Schmerzen im linken Oberbauch oder in der linken Schulterspitze sofort ärztliche Hilfe holen (möglicher Milzriss).","Bei Atemnot, Husten mit Fieber oder plötzlichen Schwellungen mit Schwindel umgehend ärztlich abklären lassen.","Knochenschmerzen lassen sich meist mit einfachen Schmerzmitteln wie Paracetamol lindern.","Im Kühlschrank lagern, nicht einfrieren."],"darreichung":["Injektionslösung (Fertigspritze)","Injektionssystem zum Aufkleben (On-body-Injektor)"]},"pegunigalsidase-alfa":{"wirkmechanismus":"Ersetzt ein fehlendes Enzym, damit sich ein Fettstoff nicht mehr in Gefässen, Nieren, Herz und Nerven ablagert. Pegunigalsidase alfa ist eine in Pflanzenzellen (Tabakzellkultur) hergestellte Alpha-Galactosidase A, deren zwei Untereinheiten über Polyethylenglykol (PEG) vernetzt sind. Dadurch ist sie stabiler und bleibt deutlich länger im Blut als bisherige Enzympräparate. In den Lysosomen spaltet sie Globotriaosylceramid (Gb3) und senkt Lyso-Gb3 im Blut.","nebenwirkungen":{"sehrHaeufig":["Infusionsbedingte Reaktionen"],"haeufig":["Überempfindlichkeitsreaktionen","Kopfschmerzen, Schwindel","Übelkeit, Bauchschmerzen, Durchfall","Juckreiz, Ausschlag","Schüttelfrost, Müdigkeit, Schwäche, Schmerzen","Gliederschmerzen"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)","Membranoproliferative Glomerulonephritis (Nierenentzündung)"]},"schwangerschaft":"Keine Erfahrungen beim Menschen. Nur anwenden, wenn eindeutig nötig.","stillzeit":"Nicht bekannt, ob Pegunigalsidase alfa in die Muttermilch übergeht. Entscheid über Stillen oder Behandlung nach ärztlicher Abwägung.","hinweise":["Wird alle 2 Wochen als Infusion in eine Vene gegeben; nach Schulung ist eine Heiminfusion möglich.","Atemnot, Schwellungen oder Ausschlag während oder nach der Infusion sofort melden.","Nierenwerte, Urin und Antikörper werden regelmässig kontrolliert."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"pegvisomant":{"wirkmechanismus":"Blockiert die Wirkung des überschüssigen Wachstumshormons im Körper. Pegvisomant ist ein gentechnisch verändertes, pegyliertes Analogon des Wachstumshormons, das an den Wachstumshormon-Rezeptor bindet, ihn aber nicht aktiviert. Dadurch sinkt die Bildung von IGF-1, das die meisten Beschwerden der Akromegalie verursacht. Die Ausschüttung von Wachstumshormon und das Wachstum des Hypophysentumors werden nicht gehemmt.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Durchfall","Gelenkschmerzen"],"haeufig":["Reaktionen an der Injektionsstelle, Lipohypertrophie (Fettgewebsverdickung)","Erhöhte Leberwerte","Übelkeit, Erbrechen, Verstopfung, Blähungen","Erhöhter oder erniedrigter Blutzucker, erhöhtes Cholesterin","Bluthochdruck","Schläfrigkeit, Schwindel, Zittern","Muskelschmerzen","Grippeähnliche Beschwerden, Müdigkeit, periphere Ödeme"],"gelegentlich":["Thrombozytopenie, Leukopenie (Mangel an Blutplättchen bzw. weissen Blutkörperchen)","Überempfindlichkeitsreaktionen","Panikattacken, Gedächtnisstörungen","Nesselsucht, Gesichtsschwellung","Eiweiss oder Blut im Urin"],"unbekannt":["Anaphylaxie, Angioödem, Kehlkopfkrampf (Laryngospasmus)"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit; die Erfahrungen sind sehr begrenzt.","stillzeit":"Nur nach ärztlicher Abwägung.","hinweise":["Täglich unter die Haut spritzen; Einstichstellen wechseln.","Leberwerte vor Beginn und in den ersten 6 Monaten regelmässig kontrollieren.","Die Wirkung wird mit dem IGF-1-Wert überwacht; Wachstumshormon-Werte sind unter Pegvisomant nicht aussagekräftig.","Bei Diabetes den Blutzucker engmaschig kontrollieren."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektionslösung"]},"pelargonium-sidoides-wurzelextrakt":{"wirkmechanismus":"Unterstützt die körpereigene Abwehr bei Atemwegsinfekten. Der Extrakt EPs 7630 enthält unter anderem Polyphenole (Proanthocyanidine) und Cumarine. In Laborstudien hemmt er das Anheften bestimmter Viren und Bakterien an Schleimhautzellen, regt die Bildung von Abwehrstoffen wie Interferon an und steigert die Schlagfrequenz der Flimmerhärchen, was den Schleimabtransport fördert. Welche Mechanismen klinisch entscheidend sind, ist nicht abschliessend geklärt.","nebenwirkungen":{"gelegentlich":["Magen-Darm-Beschwerden (Magenschmerzen, Sodbrennen, Übelkeit, Durchfall)"],"selten":["Leichtes Zahnfleisch- oder Nasenbluten","Überempfindlichkeitsreaktionen der Haut (Ausschlag, Nesselsucht, Juckreiz)"],"sehrSelten":["Schwere Überempfindlichkeitsreaktionen mit Gesichtsschwellung, Atemnot und Blutdruckabfall"],"unbekannt":["Leberschädigung, erhöhte Leberwerte"]},"schwangerschaft":"Mangels ausreichender Daten vorsichtshalber nicht anwenden.","stillzeit":"Mangels ausreichender Daten vorsichtshalber nicht anwenden.","hinweise":["Bessern sich die Beschwerden nach einer Woche nicht oder treten hohes Fieber, Atemnot oder blutiger Auswurf auf, ärztlich abklären.","Bei Zeichen einer Leberschädigung (Gelbfärbung von Haut oder Augen, dunkler Urin, Oberbauchschmerzen) sofort absetzen.","Die Tropfen enthalten Alkohol."],"darreichung":["Tropfen (Lösung zum Einnehmen)","Filmtabletten","Sirup"]},"pembrolizumab":{"wirkmechanismus":"Löst eine Bremse des Immunsystems, sodass körpereigene Abwehrzellen Krebszellen wieder erkennen und angreifen. Pembrolizumab ist ein humanisierter IgG4-Antikörper gegen den Rezeptor PD-1 auf T-Lymphozyten. Er verhindert, dass die vom Tumor gebildeten Liganden PD-L1 und PD-L2 an PD-1 binden und die T-Zellen abschalten. Weil diese Immunbremse auch gesundes Gewebe schützt, können immunvermittelte Entzündungen in praktisch allen Organen auftreten.","nebenwirkungen":{"sehrHaeufig":["Hypothyreose (Schilddrüsenunterfunktion)","Appetitlosigkeit","Kopfschmerzen","Husten, Atemnot","Durchfall, Übelkeit, Erbrechen, Bauchschmerzen, Verstopfung","Juckreiz, Hautausschlag","Muskel-, Knochen- und Gelenkschmerzen","Müdigkeit, Schwäche, Ödeme, Fieber, Anämie"],"haeufig":["Hyperthyreose (Schilddrüsenüberfunktion)","Pneumonitis (Lungenentzündung durch Immunreaktion), Pneumonie","Kolitis (Dickdarmentzündung), Mundtrockenheit","Hepatitis, erhöhte Leberwerte","Infusionsreaktionen","Schwere Hautreaktionen, Vitiligo (Weissfleckenkrankheit), trockene Haut, Haarausfall","Herzrhythmusstörungen (inkl. Vorhofflimmern), Bluthochdruck","Hyponatriämie, Hypokaliämie, Thrombozytopenie, Neutropenie, Myositis, Arthritis"],"gelegentlich":["Nebenniereninsuffizienz, Hypophysitis (Hirnanhangdrüsenentzündung), Thyreoiditis","Typ-1-Diabetes","Nephritis (Nierenentzündung)","Pankreatitis, Magen-Darm-Geschwüre","Uveitis (Augenentzündung)","Perikarderguss, Perikarditis","Psoriasis, lichenoide Hautveränderungen"],"selten":["Myokarditis (Herzmuskelentzündung)","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse","Guillain-Barré-Syndrom, Myasthenie-Syndrom, Enzephalitis, Myelitis","Immunthrombozytopenie, hämolytische Anämie, hämophagozytische Lymphohistiozytose (HLH)","Sklerosierende Cholangitis, Dünndarmperforation","Sarkoidose, Vaskulitis"],"unbekannt":["Abstossung transplantierter Organe"]},"schwangerschaft":"Nicht anwenden, ausser bei zwingender Indikation (der Antikörper gelangt zum Kind). Frauen müssen während und mindestens 4 Monate nach der letzten Dosis sicher verhüten.","stillzeit":"Unbekannt, ob Pembrolizumab in die Muttermilch übergeht; ein Risiko für das Kind ist nicht auszuschliessen – nach ärztlicher Abwägung entscheiden.","hinweise":["Neue oder stärkere Beschwerden – Durchfall, Bauchschmerzen, Husten, Atemnot, Hautausschlag, Gelbsucht, starke Müdigkeit, Kopfschmerzen, Sehstörungen – sofort melden, auch Wochen bis Monate nach der letzten Gabe.","Die Patientenkarte immer mitführen und bei jedem Arztbesuch zeigen.","Schilddrüsen-, Leber- und Nierenwerte sowie der Blutzucker werden regelmässig kontrolliert."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"pemetrexed":{"wirkmechanismus":"Hemmt die Teilung von Krebszellen, indem es den Folsäure-Stoffwechsel blockiert. Pemetrexed hemmt als Mehrfach-Folsäureantagonist die Enzyme Thymidylat-Synthase, Dihydrofolat-Reduktase und Glycinamid-Ribonukleotid-Formyltransferase, die für die Bildung von DNA-Bausteinen (Thymidin und Purine) nötig sind. In der Zelle wird es zu Polyglutamaten umgebaut, die länger in den Tumorzellen verbleiben und stärker wirken. Die vorbeugende Gabe von Folsäure und Vitamin B12 schützt gesunde Zellen und senkt die Toxizität.","nebenwirkungen":{"sehrHaeufig":["Neutropenie, Leukopenie, Anämie (Blutbildveränderungen)","Übelkeit, Erbrechen, Appetitlosigkeit","Entzündung von Mund- und Rachenschleimhaut","Durchfall, Verstopfung","Müdigkeit","Hautausschlag, Schuppung der Haut"],"haeufig":["Thrombozytopenie","Infektionen, Fieber bei Neutropenie","Flüssigkeitsmangel (Dehydratation)","Geschmacksstörung, Nervenschädigung mit Kribbeln (sensorische Neuropathie)","Bindehautentzündung, trockene oder tränende Augen","Erhöhte Leberwerte","Haarausfall, Juckreiz","Nierenfunktionsstörung bis Nierenversagen"],"gelegentlich":["Sepsis (Blutvergiftung)","Herzinfarkt, Angina pectoris, Schlaganfall, Herzrhythmusstörungen","Lungenembolie","Interstitielle Pneumonitis (Lungenentzündung)","Magen-Darm-Blutungen, Darmdurchbruch, Kolitis","Panzytopenie (Mangel aller Blutzellen)"],"selten":["Autoimmunhämolytische Anämie (Blutzerfall)","Anaphylaktischer Schock","Hepatitis (Leberentzündung)","Strahlenreaktion in früher bestrahlter Haut (Radiation recall)"],"sehrSelten":["Stevens-Johnson-Syndrom und toxische epidermale Nekrolyse","Blasenbildende Hauterkrankungen (z. B. Pemphigoid)"],"unbekannt":["Nephrogener Diabetes insipidus","Schädigung der Nierenkanälchen (Tubulusnekrose)"]},"schwangerschaft":"Nicht anwenden, ausser bei zwingender Notwendigkeit (fruchtschädigend). Frauen und Männer müssen während und einige Monate nach der Behandlung zuverlässig verhüten.","stillzeit":"Kontraindiziert.","hinweise":["Vorbehandlung zwingend: Folsäure täglich ab etwa 1 Woche vor der ersten Infusion, Vitamin-B12-Spritzen alle 9 Wochen und Dexamethason rund um jede Infusion – senkt schwere Blutbild- und Hautreaktionen.","Schmerzmittel wie Ibuprofen nur nach Rücksprache mit dem Behandlungsteam einnehmen.","Regelmässige Kontrollen von Blutbild und Nierenwerten; Fieber, Atemnot oder starken Durchfall sofort melden."],"darreichung":["Pulver zur Herstellung eines Infusionslösungskonzentrats","Konzentrat zur Herstellung einer Infusionslösung"]},"pentosanpolysulfat":{"wirkmechanismus":"Lagert sich an die Blasenschleimhaut an und stärkt deren Schutzschicht. Pentosanpolysulfat ist ein halbsynthetisches, heparinähnliches Polysaccharid, das nach Ausscheidung in den Urin die geschädigte Glykosaminoglykan-Schicht der Blasenwand ergänzt. Dadurch gelangen reizende Urinbestandteile weniger an das darunterliegende Gewebe, was Schmerzen und Harndrang vermindert. Zusätzlich wirkt es schwach gerinnungshemmend und fibrinolytisch.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Schwindel","Übelkeit, Durchfall, Verdauungsbeschwerden, Bauchschmerzen, Blähbauch","Blut im Stuhl (rektale Blutung)","Haarausfall","Rückenschmerzen, Beckenschmerzen","Periphere Ödeme (Wassereinlagerungen), Schwäche","Infektionen, Grippe"],"gelegentlich":["Blutarmut, Blutergüsse, Blutungen","Thrombozytopenie, Leukopenie (Mangel an Blutplättchen bzw. weissen Blutkörperchen)","Lichtempfindlichkeit","Appetitlosigkeit, Gewichtsveränderungen","Kribbeln oder Überempfindlichkeit der Haut","Tränenfluss, Sehschwäche","Hautausschlag","Muskel- und Gelenkschmerzen"],"unbekannt":["Pigmentäre Makulopathie (Netzhautschädigung mit Sehstörungen, v. a. bei Langzeitanwendung)","Blutgerinnungsstörungen","Allergische Reaktionen","Leberfunktionsstörungen"]},"schwangerschaft":"Keine ausreichenden Daten; Anwendung nicht empfohlen.","stillzeit":"Keine Daten; Anwendung nicht empfohlen.","hinweise":["Kapseln mit Wasser mindestens 1 Stunde vor oder 2 Stunden nach einer Mahlzeit einnehmen.","Vor Beginn und regelmässig während der Behandlung die Netzhaut augenärztlich kontrollieren lassen; Sehveränderungen sofort melden.","Die Wirkung tritt verzögert ein; nach 6 Monaten wird der Nutzen ärztlich beurteilt.","Vor Operationen die Einnahme angeben (leicht erhöhte Blutungsneigung)."],"darreichung":["Hartkapseln"]},"pentoxifyllin":{"wirkmechanismus":"Verbessert die Fliesseigenschaften des Blutes und damit die Durchblutung kleiner Gefässe. Pentoxifyllin ist ein Xanthinderivat, das Phosphodiesterasen hemmt; es erhöht die Verformbarkeit der roten Blutkörperchen, senkt Blutviskosität und Fibrinogen und hemmt die Zusammenlagerung von Blutplättchen und weissen Blutkörperchen. Ein Teil der Wirkung geht auf aktive Abbauprodukte zurück.","nebenwirkungen":{"haeufig":["Magen-Darm-Beschwerden wie Magendruck, Völlegefühl, Übelkeit, Erbrechen, Durchfall"],"gelegentlich":["Hitzegefühl mit Gesichtsrötung (Flush)","Schwindel, Kopfschmerzen, Zittern","Herzrasen (Tachykardie)","Überempfindlichkeitsreaktionen der Haut (Juckreiz, Rötung, Nesselsucht)"],"selten":["Angina pectoris (Brustenge)","Blutdruckabfall","Blutungen (Haut, Schleimhaut, Magen-Darm-Trakt)","Thrombozytopenie (Mangel an Blutplättchen)"],"sehrSelten":["Anaphylaxie (schwere allergische Reaktion)","Gallenstau und Anstieg der Leberwerte","Hypoglykämie (Unterzuckerung)","Aseptische Hirnhautentzündung"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; in der Schwangerschaft nicht anwenden.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; nur nach strenger ärztlicher Abwägung.","hinweise":["Retardtabletten unzerkaut nach dem Essen mit reichlich Flüssigkeit einnehmen.","Bei gleichzeitiger Einnahme von Blutverdünnern die Gerinnungswerte häufiger kontrollieren lassen und Blutungszeichen ärztlich melden.","Gehtraining und Rauchstopp bleiben die wichtigsten Massnahmen bei Schaufensterkrankheit."],"darreichung":["Retardtabletten"]},"perindopril":{"wirkmechanismus":"Senkt den Blutdruck, indem es die Bildung des gefässverengenden Hormons Angiotensin II blockiert. Perindopril ist ein Prodrug, das im Körper zu Perindoprilat aktiviert wird; dieses hemmt das Angiotensin-Konversionsenzym (ACE). Angiotensin II und Aldosteron sinken, die Gefässe weiten sich und die Niere scheidet mehr Salz und Wasser aus, was Herz und Gefässe entlastet. Weil ACE auch Bradykinin abbaut, steigt dessen Spiegel – das erklärt Reizhusten und Angioödeme.","nebenwirkungen":{"haeufig":["Schwindel, Kopfschmerzen, Kribbeln (Parästhesien), Drehschwindel","Sehstörungen, Ohrensausen (Tinnitus)","Hypotonie (tiefer Blutdruck)","Trockener Reizhusten, Atemnot","Bauchschmerzen, Verstopfung, Durchfall, Übelkeit, Erbrechen, Verdauungsstörungen, Geschmacksstörung","Juckreiz, Hautausschlag","Muskelkrämpfe","Schwäche (Asthenie)"],"gelegentlich":["Hyperkaliämie (erhöhtes Kalium), Hyponatriämie (Natriummangel), Hypoglykämie (Unterzuckerung)","Stimmungsschwankungen, Schlafstörungen, Depression, Schläfrigkeit","Synkope (Ohnmacht), Herzklopfen, beschleunigter Puls","Bronchospasmus (Verkrampfung der Atemwege)","Angioödem (Schwellung von Gesicht, Lippen, Zunge, Rachen), Nesselsucht, Lichtempfindlichkeit","Niereninsuffizienz, Anstieg von Harnstoff und Kreatinin","Erektionsstörungen","Mundtrockenheit, Gelenk- und Muskelschmerzen, Brustschmerzen, Ödeme, Fieber, Stürze"],"selten":["Akutes Nierenversagen","Verschlechterung einer Psoriasis","Anstieg von Leberwerten und Bilirubin","SIADH (Syndrom der inadäquaten ADH-Sekretion)","Flush (Hautrötung)"],"sehrSelten":["Agranulozytose, Panzytopenie, Leukopenie, Thrombozytopenie","Hämolytische Anämie bei G6PD-Mangel","Verwirrtheit","Herzrhythmusstörungen, Angina pectoris, Herzinfarkt oder Schlaganfall (infolge starken Blutdruckabfalls bei Risikopatienten)","Eosinophile Pneumonie, Schnupfen","Pankreatitis, Hepatitis","Erythema multiforme"],"unbekannt":["Raynaud-Syndrom"]},"schwangerschaft":"Im 1. Drittel nicht empfohlen; im 2. und 3. Drittel kontraindiziert, da fruchtschädigend (Nierenschäden, Fruchtwassermangel, verzögerte Schädelverknöcherung). Bei Kinderwunsch oder festgestellter Schwangerschaft rasch ärztlich auf ein anderes Mittel umstellen.","stillzeit":"Nicht empfohlen, da Daten fehlen; besser untersuchte Alternativen wählen, besonders bei Neugeborenen und Frühgeborenen.","hinweise":["Am besten morgens vor dem Frühstück einnehmen.","Bei Schwellung von Gesicht, Lippen, Zunge oder Rachen oder bei Atemnot sofort den Notruf wählen (Angioödem, auch nach langer Einnahme möglich).","Ein anhaltender trockener Reizhusten ist eine typische Nebenwirkung – ärztlich besprechen, nicht eigenmächtig absetzen.","Kalium und Nierenwerte regelmässig kontrollieren; kaliumhaltige Salzersatzmittel nur nach ärztlicher Rücksprache. Bei starkem Durchfall oder Erbrechen ärztlich klären, ob die Einnahme pausiert werden soll."],"darreichung":["Filmtabletten"]},"permethrin":{"wirkmechanismus":"Wirkt als Nervengift auf Milben und Läuse. Permethrin verzögert das Schliessen der spannungsabhängigen Natriumkanäle in den Nervenzellen der Parasiten; die Dauererregung führt zu Lähmung und Tod. Über die Haut wird beim Menschen nur sehr wenig aufgenommen und rasch zu unwirksamen Stoffen abgebaut.","nebenwirkungen":{"haeufig":["Brennen, Stechen oder Kribbeln der Haut (Parästhesien)","Juckreiz","Hautrötung"],"unbekannt":["Allergische Hautreaktionen (Kontaktekzem)","Trockene Haut","Reizung der Kopfhaut (Läusemittel)"]},"schwangerschaft":"Skabies-Creme im ersten Schwangerschaftsdrittel kontraindiziert, danach nur nach ärztlicher Abwägung. Läusemittel nur nach ärztlicher Rücksprache.","stillzeit":"Nach Behandlung mit der Skabies-Creme 5 Tage nicht stillen. Läusemittel nur nach ärztlicher Rücksprache.","hinweise":["Krätze: Creme dünn auf den ganzen Körper vom Hals bis zu den Zehen auftragen (auch Handflächen, Fusssohlen, unter den Nägeln, Genitalbereich), mindestens 8 Stunden einwirken lassen, dann abwaschen; bei Kleinkindern und älteren Menschen auch Gesicht und Kopfhaut, aber nicht um Augen und Mund.","Alle Kontaktpersonen gleichzeitig behandeln; Wäsche, Bettwäsche und Handtücher bei mindestens 60 °C waschen oder 3 Tage luftdicht verpacken.","Der Juckreiz kann nach erfolgreicher Behandlung noch 2–4 Wochen anhalten und ist kein Zeichen eines Therapieversagens.","Bei Kopfläusen nach 8–10 Tagen kontrollieren und gemäss Packungsbeilage nachbehandeln; Nissen mit einem Läusekamm entfernen."],"darreichung":["Creme","Haarlösung gegen Kopfläuse"]},"pfefferminzoel":{"wirkmechanismus":"Entspannt die verkrampfte Darmmuskulatur und lindert so Krämpfe und Blähungen. Der Hauptbestandteil Menthol hemmt den Calciumeinstrom in die glatten Muskelzellen der Darmwand (calciumantagonistische Wirkung) und wirkt dadurch krampflösend. Die magensaftresistente Hülle sorgt dafür, dass das Öl erst im Dünn- und Dickdarm freigesetzt wird und nicht schon im Magen Sodbrennen auslöst.","nebenwirkungen":{"unbekannt":["Sodbrennen","Brennen in der Analgegend (perianales Brennen)","Übelkeit, Erbrechen","Allergische Reaktionen auf Menthol (Hautausschlag, Kopfschmerzen, Muskelzittern)","Verschwommenes Sehen","Brennen beim Wasserlassen, Mentholgeruch von Urin und Stuhl","Anaphylaxie (schwere allergische Reaktion), sehr selten"]},"schwangerschaft":"Zur Anwendung in der Schwangerschaft liegen keine ausreichenden Daten vor; nicht empfohlen.","stillzeit":"Menthol kann in die Muttermilch übergehen; die Anwendung in der Stillzeit wird nicht empfohlen.","hinweise":["Kapseln unzerkaut mit etwas Wasser schlucken, nicht öffnen oder zerbeissen (sonst Reizung von Mund und Speiseröhre).","Vor den Mahlzeiten einnehmen, nicht zusammen mit Essen oder Säurebindern.","Bessern sich die Beschwerden nicht innerhalb von zwei Wochen, ärztlichen Rat einholen."],"darreichung":["Magensaftresistente Kapseln"]},"phenoxymethylpenicillin":{"wirkmechanismus":"Tötet Bakterien ab, indem es den Aufbau ihrer Zellwand stört. Phenoxymethylpenicillin hemmt wie alle Penicilline die Penicillin-bindenden Proteine (Transpeptidasen) und damit die Quervernetzung des Peptidoglykans (bakterizide Wirkung). Im Gegensatz zu Benzylpenicillin ist es säurestabil und kann deshalb geschluckt werden. Das Wirkspektrum ist schmal – vor allem Streptokokken, Pneumokokken und Borrelien; Beta-Laktamase-bildende Keime wie die meisten Staphylokokken sind resistent.","nebenwirkungen":{"haeufig":["Übelkeit, Erbrechen","Durchfall, Bauchschmerzen"],"gelegentlich":["Allergische Hautreaktionen (Ausschlag, Nesselsucht, Juckreiz)","Entzündung von Mundschleimhaut oder Zunge"],"selten":["Anaphylaxie (schwere allergische Reaktion) und Angioödem (Schwellung von Gesicht und Rachen)"],"sehrSelten":["Blutbildveränderungen (Neutropenie, Thrombozytopenie, hämolytische Anämie)","Pseudomembranöse Kolitis (schwere Darmentzündung)","Interstitielle Nephritis (Nierenentzündung)","Schwere Hautreaktionen (z. B. Stevens-Johnson-Syndrom)"],"unbekannt":["Pilzinfektionen (Mund, Scheide)","Schwarze Haarzunge","Jarisch-Herxheimer-Reaktion"]},"schwangerschaft":"Erlaubt; langjährige Erfahrung ohne Hinweise auf eine Schädigung des Kindes.","stillzeit":"Erlaubt; nur geringe Mengen gehen in die Muttermilch über (beim Säugling Durchfall oder Pilzbefall möglich).","hinweise":["Die Einnahmen gleichmässig über den Tag verteilen und die verordnete Behandlungsdauer einhalten, auch wenn die Beschwerden rasch abklingen – besonders bei Streptokokken-Angina.","Bei Hautausschlag, Atemnot oder Schwellungen sofort ärztlichen Rat einholen.","Schwerer oder blutiger Durchfall, auch nach Behandlungsende, muss ärztlich abgeklärt werden."],"darreichung":["Filmtabletten","Suspension oder Sirup zum Einnehmen"]},"phenprocoumon":{"wirkmechanismus":"Hemmt die Blutgerinnung, indem es die Wirkung von Vitamin K in der Leber blockiert. Phenprocoumon hemmt die Vitamin-K-Epoxid-Reduktase (VKORC1); dadurch werden die Gerinnungsfaktoren II, VII, IX und X sowie die Gerinnungshemmer Protein C und S nicht mehr funktionsfähig gebildet. Die volle Wirkung setzt erst nach einigen Tagen ein, weil die vorhandenen Faktoren zuerst abgebaut werden müssen; zu Beginn wird daher oft überlappend Heparin gegeben. Wegen der sehr langen Halbwertszeit von rund 150 Stunden hält die Wirkung nach dem Absetzen 1–2 Wochen an; die Dosis wird über den INR-Wert gesteuert, Gegenmittel ist Vitamin K.","nebenwirkungen":{"sehrHaeufig":["Blutungen unterschiedlicher Schwere – meist leicht (Zahnfleisch- und Nasenbluten, Blutergüsse, Blut im Urin), seltener schwer (Magen-Darm-Blutung, Hirnblutung)"],"gelegentlich":["Übelkeit, Appetitlosigkeit, Erbrechen, Durchfall","Vorübergehender Haarausfall","Hautausschlag, Juckreiz, Nesselsucht"],"selten":["Cumarin-Nekrose (Absterben von Hautarealen), meist in den ersten Behandlungstagen und bei Protein-C-Mangel"],"sehrSelten":["Purple-toe-Syndrom (schmerzhafte violette Verfärbung der Zehen)","Gefässentzündung (Vaskulitis)"],"unbekannt":["Leberentzündung (Hepatitis) bis hin zu schweren Leberschäden","Osteoporose bei langdauernder Anwendung","Calciphylaxie (schmerzhafte Hautgeschwüre durch Gefässverkalkung), vor allem bei Nierenkrankheit"]},"schwangerschaft":"Kontraindiziert: Phenprocoumon kann das Kind schädigen (Cumarin-Embryopathie, Blutungen). Frauen im gebärfähigen Alter müssen sicher verhüten; bei Kinderwunsch oder Schwangerschaft umgehend ärztlich auf Heparin umstellen.","stillzeit":"Geht in die Muttermilch über; Stillen nur nach ärztlicher Abwägung – das Kind erhält dann vorsorglich Vitamin K und wird auf Blutungszeichen überwacht.","hinweise":["Regelmässige INR-Kontrollen einhalten; Antikoagulationsausweis mitführen und alle Ärztinnen, Ärzte, Zahnärzte und Apotheken informieren.","Keine neuen Medikamente, auch keine rezeptfreien Schmerzmittel oder pflanzlichen Mittel (z. B. Johanniskraut), ohne Rücksprache – viele verändern den INR.","Ernährung gleichmässig halten: die Menge Vitamin-K-reicher Lebensmittel (Kohl, Spinat, Sauerkraut, grünes Blattgemüse) nicht plötzlich stark ändern; Alkohol nur in kleinen Mengen.","Wegen der langen Wirkdauer Operationen und Zahnextraktionen frühzeitig ärztlich planen; bei Zeichen einer Blutung (schwarzer Stuhl, Blut im Urin, starke Kopfschmerzen) sofort ärztliche Hilfe holen."],"darreichung":["Tabletten"]},"phenylephrin":{"wirkmechanismus":"Verengt Blutgefässe und lässt dadurch geschwollene Schleimhäute abschwellen bzw. hebt den Blutdruck. Phenylephrin stimuliert gezielt Alpha-1-Rezeptoren der glatten Muskulatur und hat kaum Wirkung auf Beta-Rezeptoren. Am Auge zieht es den Pupillenerweiterer-Muskel zusammen und erweitert so die Pupille, ohne die Naheinstellung (Akkommodation) wesentlich zu lähmen. Als Injektion erhöht es den Gefässwiderstand und damit den Blutdruck; der Puls kann reflektorisch langsamer werden.","nebenwirkungen":{"unbekannt":["Augentropfen: Brennen, vorübergehend verschwommenes Sehen, Blendempfindlichkeit, Rötung des Auges","Augentropfen (v. a. 10 %): Blutdruckanstieg, Herzklopfen","Nasenpräparate: Brennen, Trockenheit der Nasenschleimhaut, Niesen","Rebound-Schwellung und Dauerschnupfen (Rhinitis medicamentosa) bei längerer Anwendung","Bluthochdruck, Herzklopfen, Reflex-Bradykardie (verlangsamter Puls)","Herzrhythmusstörungen","Kopfschmerzen, Unruhe, Schlaflosigkeit, Zittern","Übelkeit","Harnverhalt","Allergische Reaktionen"]},"schwangerschaft":"Erkältungs- und Nasenmittel mit Phenylephrin in der Schwangerschaft möglichst meiden, besonders im ersten Drittel. Augentropfen und Injektion nur nach ärztlicher Abwägung.","stillzeit":"Orale Erkältungsmittel mit Phenylephrin in der Stillzeit nicht empfohlen. Kurzfristige Anwendung als Augen- oder Nasentropfen nach ärztlicher Rücksprache möglich.","hinweise":["Nasenpräparate höchstens 5–7 Tage ohne Unterbruch anwenden, sonst droht Dauerschnupfen.","Nach pupillenerweiternden Augentropfen ist die Sicht für einige Stunden verschwommen und blendempfindlich – nicht selbst Auto fahren.","Nicht mehrere Erkältungsmittel gleichzeitig verwenden; bei Kombipräparaten die Paracetamol-Höchstdosis beachten.","Bei Bluthochdruck oder Herzkrankheiten vor der Anwendung in der Apotheke oder ärztlich beraten lassen."],"darreichung":["Augentropfen","Nasenspray","Nasentropfen","Nasengel","Pulver zum Auflösen (Beutel)","Injektionslösung"]},"phytomenadion":{"wirkmechanismus":"Ermöglicht der Leber die Bildung funktionsfähiger Gerinnungsfaktoren. Vitamin K1 ist der Kofaktor der Gamma-Glutamyl-Carboxylase, die die Gerinnungsfaktoren II, VII, IX und X sowie die Gerinnungshemmer Protein C und S erst aktiv macht. Vitamin-K-Antagonisten blockieren die Rückgewinnung von Vitamin K; zugeführtes Phytomenadion umgeht diese Blockade. Die Wirkung setzt nicht sofort ein, sondern erst nach einigen Stunden, weil die Faktoren neu gebildet werden müssen; bei lebensbedrohlicher Blutung werden deshalb zusätzlich Gerinnungsfaktoren (Prothrombinkomplex) gegeben.","nebenwirkungen":{"unbekannt":["Überempfindlichkeits- und anaphylaktoide Reaktionen bis Schock, Herz- und Atemstillstand (v. a. bei intravenöser Gabe)","Venenreizung oder Venenentzündung an der Injektionsstelle","Reaktionen an der Injektionsstelle (bei Neugeborenen)"]},"schwangerschaft":"Keine Hinweise auf eine Schädigung; nur bei klarer Indikation anwenden. Eine Gabe an die Schwangere zur Vorbeugung von Blutungen beim Neugeborenen wird nicht empfohlen.","stillzeit":"Nur geringe Mengen gehen in die Muttermilch über; Anwendung möglich. Gestillte Neugeborene brauchen trotzdem ihre eigene Vitamin-K-Prophylaxe.","hinweise":["Wirkt nicht gegen Heparine und direkte orale Antikoagulanzien (z. B. Rivaroxaban, Apixaban, Dabigatran).","Intravenös nur langsam spritzen; bei Erwachsenen nicht in den Muskel spritzen (Blutergussgefahr unter Gerinnungshemmung).","Nach der Aufhebung einer Vitamin-K-Antagonisten-Wirkung den INR kontrollieren lassen.","In der Schweiz erhalten Neugeborene routinemässig Vitamin K nach einem festen Schema in den ersten Lebenswochen."],"darreichung":["Injektionslösung in Ampullen (auch zum Einnehmen)"]},"pimecrolimus":{"wirkmechanismus":"Dämpft die Entzündung in der Haut, ohne Kortison zu enthalten und ohne die Haut dünner zu machen. Pimecrolimus bindet an Macrophilin-12 und hemmt so das Enzym Calcineurin in T-Zellen und Mastzellen. Dadurch werden entzündungsfördernde Botenstoffe (Zytokine) und die Freisetzung von Entzündungsmediatoren gehemmt. Über die Haut gelangt nur sehr wenig in den Blutkreislauf.","nebenwirkungen":{"sehrHaeufig":["Brennen an der Auftragsstelle"],"haeufig":["Reaktionen an der Auftragsstelle (Reizung, Juckreiz, Rötung)","Hautinfektionen (Follikulitis)"],"gelegentlich":["Furunkel, Impetigo, Herpes simplex, Gürtelrose","Molluscum contagiosum (Dellwarzen)","Verschlechterung der Neurodermitis"],"selten":["Alkoholunverträglichkeit (Gesichtsrötung, Hautreizung nach Alkohol)","Allergische Reaktionen, Hautverfärbung"],"sehrSelten":["Anaphylaxie (schwere allergische Reaktion)"],"unbekannt":["Lymphome und Hauttumoren (Zusammenhang nicht gesichert)"]},"schwangerschaft":"Nur nach ärztlicher Abwägung; es liegen kaum Erfahrungen vor, die Aufnahme in den Körper ist jedoch sehr gering.","stillzeit":"Nur nach ärztlicher Abwägung; nicht auf die Brust auftragen.","hinweise":["Zweimal täglich dünn auftragen; Besserung meist innert weniger Tage. Ohne Besserung nach 6 Wochen ärztlich neu beurteilen lassen.","Nicht unter luftdichten Verbänden anwenden; Kontakt mit Augen und Schleimhäuten vermeiden.","Sonnenschutz und Meiden von Solarium; Alkohol kann Gesichtsrötung auslösen."],"darreichung":["Creme"]},"pindolol":{"wirkmechanismus":"Senkt den Blutdruck und entlastet das Herz, indem es die Wirkung der Stresshormone Adrenalin und Noradrenalin am Herzen abschwächt. Pindolol blockiert Beta-1- und Beta-2-Rezeptoren ohne Selektivität und besitzt zugleich eine ausgeprägte partielle agonistische Eigenwirkung (intrinsische sympathomimetische Aktivität, ISA). Deshalb sinken Ruhepuls und Herzauswurf weniger stark als unter anderen Betablockern, während der Anstieg von Puls und Blutdruck unter Belastung gedämpft wird.","nebenwirkungen":{"haeufig":["Schwindel, Müdigkeit, Kopfschmerzen","Schlafstörungen","Magen-Darm-Beschwerden (Übelkeit, Durchfall)"],"unbekannt":["Bradykardie (langsamer Puls), AV-Block","Verschlechterung einer Herzinsuffizienz","Bronchospasmus (Verkrampfung der Atemwege)","Kalte Hände und Füsse, Verschlechterung von Durchblutungsstörungen","Muskelkrämpfe, Zittern","Depressive Verstimmung, lebhafte Träume","Hautausschlag, Verschlechterung einer Psoriasis"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Betablocker können das Wachstum des Kindes vermindern und beim Neugeborenen langsamen Puls und Unterzuckerung verursachen.","stillzeit":"Pindolol geht in die Muttermilch über; nicht empfohlen bzw. nur nach strenger ärztlicher Abwägung.","hinweise":["Nicht abrupt absetzen – Gefahr von Angina-pectoris-Anfällen, Herzinfarkt und Blutdruckanstieg; über 1–2 Wochen ausschleichen.","Vor Operationen die Behandlung angeben.","Kann besonders zu Beginn und zusammen mit Alkohol die Fahrtüchtigkeit beeinträchtigen."],"darreichung":["Tabletten"]},"pioglitazon":{"wirkmechanismus":"Macht die Körperzellen wieder empfindlicher für Insulin. Pioglitazon aktiviert den Kernrezeptor PPAR-gamma (peroxisome proliferator-activated receptor gamma) vor allem im Fettgewebe, aber auch in Muskel und Leber. Dadurch werden Gene des Zucker- und Fettstoffwechsels reguliert: Die Zellen nehmen mehr Glucose auf, die Zuckerneubildung in der Leber sinkt. Die volle Wirkung entwickelt sich erst über mehrere Wochen; allein verursacht Pioglitazon keine Unterzuckerung.","nebenwirkungen":{"haeufig":["Gewichtszunahme","Ödeme (Wassereinlagerungen), besonders in Kombination mit Insulin","Herzinsuffizienz in Kombination mit Insulin","Infektionen der oberen Atemwege","Hypästhesie (Taubheitsgefühl)","Sehstörungen","Knochenbrüche"],"gelegentlich":["Blasenkrebs","Sinusitis (Nasennebenhöhlenentzündung)","Schlaflosigkeit"],"unbekannt":["Makulaödem (Schwellung der Netzhautmitte)","Erhöhte Leberwerte, Leberentzündung","Überempfindlichkeitsreaktionen (Angioödem, Ausschlag, Nesselsucht)"]},"schwangerschaft":"Nicht anwenden; ein Diabetes in der Schwangerschaft wird mit Insulin behandelt.","stillzeit":"Nicht anwenden, da Pioglitazon in die Muttermilch übergehen kann.","hinweise":["Regelmässig wiegen: rasche Gewichtszunahme, geschwollene Beine oder Atemnot sofort ärztlich melden (mögliche Herzinsuffizienz).","Blut im Urin, Schmerzen oder plötzlicher Harndrang beim Wasserlassen ärztlich abklären lassen.","Die volle Wirkung zeigt sich erst nach einigen Wochen; die Leberwerte werden regelmässig kontrolliert."],"darreichung":["Tabletten"]},"pipamperon":{"wirkmechanismus":"Wirkt vor allem beruhigend und schlaffördernd, kaum antipsychotisch im engeren Sinn. Pipamperon blockiert vor allem Serotonin-5-HT2A- und Dopamin-D4-Rezeptoren, schwächer auch Dopamin-D2- sowie Alpha-1-Rezeptoren. Wegen der schwachen D2-Blockade treten Bewegungsstörungen seltener auf als bei hochpotenten Antipsychotika wie Haloperidol.","nebenwirkungen":{"haeufig":["Schläfrigkeit, Müdigkeit","Extrapyramidale Störungen (Zittern, Muskelsteife, Bewegungsarmut, Sitzunruhe)"],"unbekannt":["Orthostatische Hypotonie (Blutdruckabfall beim Aufstehen), Schwindel","Herzrasen","QT-Verlängerung und Herzrhythmusstörungen","Spätdyskinesien (bleibende unwillkürliche Bewegungen)","Malignes neuroleptisches Syndrom (Fieber, Muskelsteife, Bewusstseinsstörung)","Krampfanfälle","Erhöhtes Prolaktin mit Milchfluss und Zyklusstörungen","Venöse Thromboembolie"]},"schwangerschaft":"Nur begrenzte Erfahrungen; nur nach strenger ärztlicher Abwägung. Bei Einnahme im letzten Drittel können beim Neugeborenen Bewegungsstörungen und Entzugssymptome auftreten.","stillzeit":"Ob Pipamperon in die Muttermilch übergeht, ist nicht bekannt. Während der Behandlung nicht stillen.","hinweise":["Wirkt beruhigend: Fahrtüchtigkeit beeinträchtigt; Alkohol meiden.","Langsam aufstehen, besonders nachts (Sturzgefahr durch Blutdruckabfall).","Bei hohem Fieber mit Muskelsteife sofort ärztliche Hilfe holen."],"darreichung":["Tabletten","Tropfen"]},"piperacillin-tazobactam":{"wirkmechanismus":"Tötet ein sehr breites Spektrum von Bakterien ab. Piperacillin hemmt die Penicillin-bindenden Proteine und damit den Aufbau der bakteriellen Zellwand (bakterizide Wirkung); es erfasst viele gramnegative Keime einschliesslich Pseudomonas aeruginosa sowie Anaerobier. Tazobactam hemmt zahlreiche Beta-Laktamasen und schützt Piperacillin so vor dem Abbau durch resistente Bakterien. Gegen MRSA und Carbapenemase-bildende Erreger wirkt die Kombination nicht.","nebenwirkungen":{"sehrHaeufig":["Durchfall"],"haeufig":["Candida-Infektionen (Pilzbefall)","Thrombozytopenie, Anämie","Schlaflosigkeit, Kopfschmerzen","Übelkeit, Erbrechen, Bauchschmerzen, Verstopfung, Verdauungsbeschwerden","Hautausschlag, Juckreiz","Fieber, Reaktionen an der Infusionsstelle","Anstieg von Leber- und Nierenwerten, verlängerte Gerinnungszeit, positiver Coombs-Test"],"gelegentlich":["Leukopenie (Mangel an weissen Blutkörperchen)","Hypokaliämie (Kaliummangel), tiefer Blutzucker","Blutdruckabfall, Venenentzündung, Hitzegefühl","Gelbsucht","Nesselsucht (Urtikaria)","Gelenk- und Muskelschmerzen, Schüttelfrost"],"selten":["Agranulozytose","Pseudomembranöse Kolitis (schwere Darmentzündung)","Nasenbluten, Mundschleimhautentzündung","Toxische epidermale Nekrolyse (schwere Hautablösung)"],"unbekannt":["Anaphylaxie bis zum anaphylaktischen Schock","Panzytopenie, Neutropenie, hämolytische Anämie, Eosinophilie","Leberentzündung","Stevens-Johnson-Syndrom, DRESS, AGEP","Interstitielle Nephritis, Nierenversagen","Eosinophile Pneumonie (allergische Lungenentzündung)","Hämophagozytische Lymphohistiozytose (HLH)","Krampfanfälle (vor allem bei hohen Dosen und eingeschränkter Nierenfunktion)"]},"schwangerschaft":"Nur anwenden, wenn eindeutig nötig und der Nutzen das mögliche Risiko überwiegt; beide Wirkstoffe passieren die Plazenta.","stillzeit":"Piperacillin geht in geringen Mengen in die Muttermilch über; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Wird im Spital als Infusion verabreicht.","Bei längerer Behandlung werden Blutbild, Nieren- und Leberwerte sowie Kalium kontrolliert.","Hautausschlag, Atemnot, Blutungszeichen oder schweren Durchfall sofort melden."],"darreichung":["Pulver zur Herstellung einer Infusionslösung"]},"pneumokokken-konjugatimpfstoff":{"wirkmechanismus":"Regt das Immunsystem an, Schutzstoffe gegen die häufigsten krankmachenden Pneumokokken-Typen zu bilden. Der Impfstoff enthält die Zuckerhüllen (Kapselpolysaccharide) von 13, 15 oder 20 Pneumokokken-Serotypen, gekoppelt an das ungiftige Diphtherie-Trägereiweiss CRM197. Die Koppelung führt zu einer starken, T-Zell-abhängigen Immunantwort mit Gedächtniszellen – auch bei Säuglingen, die auf reine Polysaccharid-Impfstoffe kaum ansprechen.","nebenwirkungen":{"sehrHaeufig":["Schmerzen, Rötung, Schwellung oder Verhärtung an der Einstichstelle","Fieber (Kinder)","Kinder: Reizbarkeit, Schläfrigkeit, unruhiger Schlaf, verminderter Appetit","Erwachsene: Kopfschmerzen, Müdigkeit, Muskel- und Gelenkschmerzen"],"haeufig":["Fieber über 39 °C bei Kindern","Erbrechen, Durchfall","Hautausschlag","Schüttelfrost (Erwachsene)"],"gelegentlich":["Krampfanfälle einschliesslich Fieberkrämpfe","Nesselsucht","Anhaltendes Schreien bei Säuglingen"],"selten":["Überempfindlichkeitsreaktionen mit Gesichtsschwellung, Atemnot, Bronchospasmus","Kollaps mit verminderter Ansprechbarkeit (hypoton-hyporesponsive Episode) bei Säuglingen"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)","Geschwollene Lymphknoten","Atempausen (Apnoe) bei sehr unreifen Frühgeborenen"]},"schwangerschaft":"Daten begrenzt; Impfung in der Schwangerschaft nur bei klarer Indikation nach ärztlicher Abwägung.","stillzeit":"Impfung in der Stillzeit möglich, wenn angezeigt.","hinweise":["Impfschema gemäss Schweizerischem Impfplan: Säuglinge ab 2 Monaten, Erwachsene ab 65 Jahren und Personen mit Risikofaktoren.","Kann gleichzeitig mit anderen Impfungen gegeben werden (an verschiedenen Stellen).","Nach der Impfung etwa 15 Minuten in der Praxis bleiben."],"darreichung":["Injektionssuspension (Fertigspritze, intramuskulär)"]},"policresulen":{"wirkmechanismus":"Stillt kleine Blutungen und wirkt desinfizierend. Policresulen ist eine stark saure Substanz, die Eiweisse in geschädigtem und abgestorbenem Gewebe ausfällt (koaguliert) und so kleine Gefässe verschliesst, während gesundes Gewebe weitgehend unberührt bleibt. Zusätzlich wirkt es gegen Bakterien und Pilze und unterstützt die Abheilung.","nebenwirkungen":{"unbekannt":["Lokales Brennen oder Reizgefühl, besonders zu Beginn der Behandlung","Allergische Hautreaktionen"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; nur nach ärztlicher Rücksprache anwenden.","stillzeit":"Nur nach ärztlicher Rücksprache anwenden.","hinweise":["Nach dem Stuhlgang und nach schonender Reinigung der Analregion anwenden.","Bei Blut im Stuhl oder fehlender Besserung nach einer Woche ärztlich abklären lassen."],"darreichung":["Salbe","Zäpfchen"]},"polidocanol":{"wirkmechanismus":"Verklebt und verschliesst die behandelte Vene. Polidocanol ist eine oberflächenaktive Substanz, die nach der Injektion die Innenwand (Endothel) der Vene schädigt; es bildet sich ein Gerinnsel, das die Vene verschliesst und später zu Bindegewebe umgebaut wird. Als Schaum aufbereitet verdrängt es das Blut und eignet sich auch für grössere Venen. Daneben wirkt Polidocanol örtlich betäubend.","nebenwirkungen":{"haeufig":["Blutergüsse (Hämatome) und Schmerzen an der Injektionsstelle","Bräunliche Hautverfärbung (Hyperpigmentierung)","Neue feine Äderchen (Matting)","Kleine Blutgerinnsel in der behandelten Vene"],"gelegentlich":["Oberflächliche Venenentzündung (Thrombophlebitis)","Allergische Hautreaktionen, Rötung","Hautnekrose (Absterben von Haut) an der Injektionsstelle","Verhärtung und Schwellung"],"selten":["Tiefe Venenthrombose","Schmerzen in den Beinen"],"sehrSelten":["Lungenembolie","Schlaganfall oder vorübergehende Durchblutungsstörung des Gehirns","Sehstörungen, Migräne, Kribbeln","Anaphylaxie (schwere allergische Reaktion), Angioödem","Herzrhythmusstörungen, Herzstillstand","Atemnot, Brustenge"]},"schwangerschaft":"Nicht anwenden, ausser es ist eindeutig erforderlich; Verödungen werden in der Regel auf die Zeit nach der Schwangerschaft verschoben.","stillzeit":"Keine Daten; ist eine Verödung nötig, wird eine Stillpause von 2–3 Tagen empfohlen.","hinweise":["Nach der Verödung Kompressionsstrümpfe oder -verband wie verordnet tragen und sich regelmässig bewegen.","In den ersten Tagen langes Stehen, Sauna, heisse Bäder und intensive Sonne meiden.","Bei Sehstörungen, Atemnot, Brustschmerzen, Lähmungen oder Sprachstörungen sofort ärztliche Hilfe holen."],"darreichung":["Injektionslösung"]},"polystyrolsulfonat":{"wirkmechanismus":"Bindet im Darm Kalium und sorgt dafür, dass es mit dem Stuhl ausgeschieden statt ins Blut aufgenommen wird. Polystyrolsulfonat ist ein nicht resorbierbares Kationenaustauscherharz, das Natrium- bzw. Calciumionen gegen Kaliumionen austauscht, vor allem im Dickdarm. Die Wirkung setzt erst nach Stunden ein; für die Notfallbehandlung einer lebensbedrohlichen Hyperkaliämie reicht es allein nicht aus.","nebenwirkungen":{"unbekannt":["Hypokaliämie (Kaliummangel) sowie Störungen von Calcium, Magnesium und Natrium","Übelkeit, Erbrechen, Appetitlosigkeit, Magenreizung","Verstopfung, gelegentlich Durchfall","Kotsteine (Bezoare) und Darmverschluss","Darmgeschwüre, ischämische Kolitis, Darmnekrose und Darmdurchbruch","Bronchitis oder Lungenentzündung durch eingeatmetes Pulver","Natriumüberladung mit Ödemen (Natriumsalz) bzw. Hyperkalzämie (Calciumsalz)"]},"schwangerschaft":"Keine ausreichenden Daten; das Harz wird nicht ins Blut aufgenommen. Anwendung nur nach ärztlicher Abwägung.","stillzeit":"Wird nicht ins Blut aufgenommen; Anwendung nach ärztlicher Abwägung möglich.","hinweise":["Pulver in Wasser oder etwas gesüsster Flüssigkeit aufschwemmen – nicht in kaliumreichem Fruchtsaft und nicht mit Sorbitol.","Kalium und weitere Blutsalze regelmässig kontrollieren lassen.","Bei Verstopfung, Bauchschmerzen oder Blut im Stuhl ärztlich melden."],"darreichung":["Pulver zum Einnehmen oder zur rektalen Anwendung (Einlauf)"]},"posaconazol":{"wirkmechanismus":"Hemmt die Bildung eines wichtigen Bausteins der Pilzzellwand und stoppt so das Wachstum von Hefe- und Schimmelpilzen. Posaconazol blockiert die pilzeigene Lanosterol-14α-Demethylase; dadurch fehlt Ergosterol in der Zellmembran und toxische Sterolvorstufen reichern sich an. Es wirkt auch gegen viele Mucorales (Jochpilze). Posaconazol ist ein starker Hemmer von CYP3A4 und wird selbst über Glucuronidierung (UGT) und P-Glykoprotein ausgeschieden.","nebenwirkungen":{"haeufig":["Neutropenie (Mangel an weissen Blutkörperchen)","Elektrolytstörungen, Appetitlosigkeit","Kopfschmerzen, Schwindel, Kribbeln, Schläfrigkeit, Geschmacksstörungen","Bluthochdruck","Übelkeit, Erbrechen, Bauchschmerzen, Durchfall, Verdauungsbeschwerden, Mundtrockenheit, Blähungen, Verstopfung","Erhöhte Leberwerte","Hautausschlag, Juckreiz","Fieber, Schwäche, Müdigkeit"],"gelegentlich":["Thrombozytopenie, Leukopenie, Anämie, Eosinophilie","Allergische Reaktionen","Hyperglykämie, Hypoglykämie","Krampfanfälle, Neuropathie, Zittern","Verschwommenes Sehen, Lichtscheu","QT-Verlängerung, Herzklopfen, Bradykardie, Tachykardie","Pankreatitis","Hepatitis, Gelbsucht, Leberschäden","Haarausfall","Akutes Nierenversagen, Niereninsuffizienz","Menstruationsstörungen"],"selten":["Hämolytisch-urämisches Syndrom, thrombotisch-thrombozytopenische Purpura, Panzytopenie","Nebenniereninsuffizienz","Psychose, Depression","Schlaganfall, Enzephalopathie, Ohnmacht","Doppelbilder, Hörstörungen","Torsade de pointes, plötzlicher Herztod, Herzinsuffizienz, Herzinfarkt","Lungenembolie, Thrombose, Pneumonitis","Magen-Darm-Blutung, Darmverschluss","Leberversagen","Stevens-Johnson-Syndrom"],"unbekannt":["Pseudoaldosteronismus (Bluthochdruck mit Kaliummangel)"]},"schwangerschaft":"Nicht anwenden, ausser der Nutzen überwiegt eindeutig das Risiko (im Tierversuch fruchtschädigend). Frauen im gebärfähigen Alter müssen wirksam verhüten.","stillzeit":"Mit Beginn der Behandlung abstillen.","hinweise":["Suspension immer mit einer Mahlzeit oder einem Nahrungsergänzungsgetränk einnehmen; Tabletten unzerkaut mit einer Mahlzeit schlucken.","Tabletten und Suspension sind nicht 1:1 austauschbar – nur die verordnete Form verwenden.","Vor jedem neuen Medikament die Posaconazol-Behandlung erwähnen: viele Kombinationen sind verboten.","Leberwerte, Elektrolyte und Blutdruck werden regelmässig kontrolliert."],"darreichung":["Magensaftresistente Tabletten","Suspension zum Einnehmen","Konzentrat zur Herstellung einer Infusionslösung"]},"povidon-iod":{"wirkmechanismus":"Tötet Krankheitserreger auf Haut, Schleimhaut und in Wunden ab. Povidon-Iod ist ein Komplex aus dem Trägerstoff Povidon und Iod, der laufend kleine Mengen freies Iod abgibt. Freies Iod oxidiert und iodiert Eiweisse, Enzyme und Membranbestandteile der Mikroorganismen und wirkt so rasch gegen Bakterien, Pilze, viele Viren und Protozoen; Resistenzen sind nicht bekannt. Durch die langsame Freisetzung ist es besser verträglich als alkoholische Iodlösung. Über Wunden und Schleimhäute kann jedoch Iod in den Körper aufgenommen werden.","nebenwirkungen":{"selten":["Überempfindlichkeitsreaktionen der Haut (Kontaktdermatitis mit Rötung, Bläschen, Juckreiz)"],"sehrSelten":["Anaphylaxie, Angioödem (akute allergische Reaktionen)","Schilddrüsenüberfunktion durch Iod bei vorbestehender Schilddrüsenerkrankung"],"unbekannt":["Schilddrüsenunterfunktion nach längerer oder grossflächiger Anwendung","Störungen von Elektrolyt- und Säure-Basen-Haushalt, Nierenfunktionsstörung bis Nierenversagen (nach Anwendung auf grossen Flächen, z. B. Verbrennungen)","Hautreizung bis Verätzung, wenn sich Lösung unter dem Körper ansammelt (z. B. bei Operationen)"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung, kurz und kleinflächig: Iod passiert die Plazenta und kann die Schilddrüse des ungeborenen Kindes beeinträchtigen.","stillzeit":"Nur nach strenger Abwägung, kurz und kleinflächig: Iod reichert sich in der Muttermilch an. Nicht auf die Brust auftragen; gegebenenfalls Schilddrüse des Kindes kontrollieren.","hinweise":["Die braune Farbe zeigt die Wirksamkeit an; verblasst sie, ist das Iod verbraucht.","Vor Schilddrüsenuntersuchungen die Anwendung angeben – Iod kann die Ergebnisse verfälschen.","Nicht mit anderen Desinfektionsmitteln mischen.","Flecken auf Textilien lassen sich mit warmem Wasser und Seife entfernen."],"darreichung":["Lösung","Salbe"]},"pramipexol":{"wirkmechanismus":"Ahmt im Gehirn die Wirkung des Botenstoffs Dopamin nach. Pramipexol ist ein nicht-ergoliner Dopaminagonist mit hoher Affinität zu D2- und besonders D3-Rezeptoren und stimuliert die Dopaminrezeptoren im Striatum. Dadurch bessern sich die Bewegungsbeschwerden bei Parkinson sowie Missempfindungen und Bewegungsdrang beim Restless-Legs-Syndrom. Pramipexol wird kaum abgebaut und unverändert über die Niere ausgeschieden.","nebenwirkungen":{"sehrHaeufig":["Schwindel","Schläfrigkeit (Somnolenz)","Übelkeit","Dyskinesien (Überbewegungen, bei Parkinson)"],"haeufig":["Impulskontrollstörungen und zwanghaftes Verhalten (z. B. Spielsucht, Kaufsucht, Essattacken, gesteigertes sexuelles Verlangen)","Halluzinationen, Verwirrtheit","Schlaflosigkeit, abnorme Träume","Kopfschmerzen","Sehstörungen (Doppelbilder, verschwommenes Sehen)","Hypotonie (tiefer Blutdruck)","Verstopfung, Erbrechen","Müdigkeit, Beinödeme, Gewichtsabnahme"],"gelegentlich":["Plötzliches Einschlafen","Ohnmacht (Synkope)","Wahnvorstellungen, Paranoia, Delir","Herzinsuffizienz","Lungenentzündung","SIADH (Natriummangel durch zu viel antidiuretisches Hormon)","Überempfindlichkeit, Juckreiz, Ausschlag","Gewichtszunahme"],"selten":["Manie"],"unbekannt":["Dopaminagonisten-Entzugssyndrom (Apathie, Angst, Depression, Schmerzen beim Absetzen)"]},"schwangerschaft":"Keine ausreichenden Erfahrungen beim Menschen. Nur anwenden, wenn der Nutzen das Risiko klar überwiegt.","stillzeit":"Pramipexol hemmt die Milchbildung und geht vermutlich in die Muttermilch über. Nicht stillen.","hinweise":["Mit oder ohne Mahlzeit einnehmen; Retardtabletten ganz schlucken.","Bei Tagesschläfrigkeit oder plötzlichem Einschlafen nicht Auto fahren und keine Maschinen bedienen.","Nicht abrupt absetzen, sondern ärztlich angeleitet ausschleichen.","Angehörige sollten auf Spielsucht, Kaufsucht oder auffälliges Sexualverhalten achten."],"darreichung":["Tabletten","Retardtabletten"]},"prasugrel":{"wirkmechanismus":"Verhindert, dass Blutplättchen verklumpen und Gerinnsel in den Herzkranzgefässen oder im Stent bilden. Prasugrel ist eine Vorstufe (Prodrug), die im Darm und in der Leber (u. a. über CYP3A4 und CYP2B6) rasch und zuverlässig in den aktiven Metaboliten umgewandelt wird. Dieser blockiert den ADP-Rezeptor P2Y12 der Blutplättchen irreversibel. Die Wirkung setzt schneller ein und ist stärker und gleichmässiger als bei Clopidogrel und hält für die Lebensdauer der Plättchen (7–10 Tage) an.","nebenwirkungen":{"haeufig":["Anämie (Blutarmut)","Blutergüsse (Hämatome), Hautblutungen","Nasenbluten","Magen-Darm-Blutungen","Blut im Urin","Blutungen und Blutergüsse an der Gefässpunktionsstelle","Hautausschlag"],"gelegentlich":["Überempfindlichkeitsreaktionen einschliesslich Angioödem","Hirnblutung (besonders nach früherem Schlaganfall oder TIA)","Augenblutungen","Bluthusten","Blutungen aus Zahnfleisch, Enddarm und im hinteren Bauchraum (retroperitoneal)","Nachblutungen nach Eingriffen"],"selten":["Thrombozytopenie (verminderte Blutplättchen)","Blutergüsse unter der Haut"],"unbekannt":["Thrombotisch-thrombozytopenische Purpura (TTP)"]},"schwangerschaft":"Keine Erfahrungen beim Menschen; nur anwenden, wenn der Nutzen das Risiko für das Ungeborene eindeutig überwiegt.","stillzeit":"Unbekannt, ob Prasugrel in die Muttermilch übergeht; Stillen wird nicht empfohlen.","hinweise":["Nicht eigenmächtig absetzen – nach Stent-Einlage drohen Stentverschluss und Herzinfarkt.","Vor Operationen und Zahnbehandlungen die Einnahme angeben; ein Pausieren (meist 7 Tage vorher) nur nach ärztlicher Anordnung.","Täglich etwa zur gleichen Zeit einnehmen, mit oder ohne Mahlzeit.","Bei Blutungszeichen (schwarzer Stuhl, Blut im Urin, starke Blutergüsse) oder plötzlichen neurologischen Ausfällen sofort ärztliche Hilfe holen."],"darreichung":["Filmtabletten"]},"pravastatin":{"wirkmechanismus":"Senkt das Cholesterin, indem es dessen Herstellung in der Leber bremst. Pravastatin hemmt kompetitiv die HMG-CoA-Reduktase, das Schlüsselenzym der Cholesterinsynthese. Die Leberzellen bilden daraufhin mehr LDL-Rezeptoren und entfernen mehr LDL-Cholesterin aus dem Blut. Pravastatin ist wasserlöslich, wird über den Transporter OATP1B1 in die Leber aufgenommen und kaum über Cytochrom-P450-Enzyme abgebaut – es hat deshalb weniger Wechselwirkungen als Simvastatin oder Atorvastatin.","nebenwirkungen":{"gelegentlich":["Kopfschmerzen, Schwindel","Schlafstörungen, Schlaflosigkeit","Sehstörungen (verschwommenes Sehen, Doppelbilder)","Verdauungsbeschwerden, Sodbrennen, Bauchschmerzen, Übelkeit, Erbrechen, Verstopfung, Durchfall, Blähungen","Juckreiz, Ausschlag, Nesselsucht, Veränderungen von Kopfhaut und Haaren (inkl. Haarausfall)","Störungen beim Wasserlassen (Schmerzen, häufiges oder nächtliches Wasserlassen)","Sexuelle Funktionsstörungen","Müdigkeit"],"sehrSelten":["Rhabdomyolyse (Muskelzerfall), teils mit akutem Nierenversagen; Myopathie, Myositis","Sehnenschäden, teils mit Sehnenriss","Überempfindlichkeitsreaktionen: Anaphylaxie, Angioödem, lupusähnliches Syndrom","Gelbsucht, Hepatitis, fulminante Lebernekrose","Pankreatitis (Bauchspeicheldrüsenentzündung)","Periphere Polyneuropathie, Parästhesien (Kribbeln)"],"unbekannt":["Immunvermittelte nekrotisierende Myopathie (anhaltende Muskelschwäche)","Dermatomyositis","Interstitielle Lungenerkrankung","Depression, Albträume, Gedächtnisverlust","Diabetes mellitus bei Personen mit Risikofaktoren","Myasthenia gravis (Muskelschwäche) oder deren Verschlechterung"]},"schwangerschaft":"Kontraindiziert – Cholesterin ist für die Entwicklung des Ungeborenen nötig. Bei Eintritt einer Schwangerschaft sofort absetzen; Frauen im gebärfähigen Alter sollen zuverlässig verhüten.","stillzeit":"Kontraindiziert – Pravastatin geht in geringen Mengen in die Muttermilch über.","hinweise":["Einmal täglich, vorzugsweise am Abend, mit oder ohne Essen.","Unerklärliche Muskelschmerzen, -schwäche oder -krämpfe, besonders mit Fieber oder dunklem Urin, sofort ärztlich melden.","Bei Colestyramin oder Colestipol zeitlichen Abstand einhalten (Pravastatin 1 Stunde vorher oder 4 Stunden nachher).","Ernährung und Bewegung bleiben wichtig; Blutfette und Leberwerte regelmässig kontrollieren."],"darreichung":["Tabletten"]},"prazosin":{"wirkmechanismus":"Senkt den Blutdruck, indem es die Blutgefässe erweitert. Prazosin blockiert selektiv die Alpha-1-Adrenozeptoren in der Gefässwand, sodass Noradrenalin die Gefässe nicht mehr verengen kann. Arterien und Venen erweitern sich, der periphere Widerstand sinkt, meist ohne deutlichen Anstieg der Herzfrequenz. Zusätzlich entspannt es die glatte Muskulatur von Prostata und Blasenhals.","nebenwirkungen":{"haeufig":["Schwindel, Benommenheit","Kopfschmerzen","Müdigkeit, Schwäche","Herzklopfen","Übelkeit","Ödeme (Wassereinlagerungen)","Verstopfte Nase","Verschwommenes Sehen"],"gelegentlich":["Synkope (Ohnmacht), vor allem nach der ersten Dosis","Tachykardie (Herzrasen)","Hautausschlag, Juckreiz","Häufiges Wasserlassen"],"selten":["Priapismus (schmerzhafte Dauererektion)","Harninkontinenz","Potenzstörungen"],"unbekannt":["Intraoperatives Floppy-Iris-Syndrom bei Operation am Grauen Star"]},"schwangerschaft":"Begrenzte Erfahrungen; nur anwenden, wenn der Nutzen das Risiko klar überwiegt.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; nur nach ärztlicher Abwägung.","hinweise":["Erste Dosis abends vor dem Schlafengehen einnehmen; in den ersten Tagen langsam aufstehen.","Schwindel und Benommenheit können besonders zu Beginn die Fahrtüchtigkeit beeinträchtigen.","Vor einer Augenoperation (Grauer Star) die Einnahme angeben."],"darreichung":["Tabletten"]},"prednicarbat":{"wirkmechanismus":"Dämpft Entzündung, Rötung und Juckreiz der Haut. Prednicarbat ist ein nicht halogenierter Doppelester des Prednisolons, der in der Haut zu wirksamen Abbauprodukten gespalten wird; diese binden an Glukokortikoid-Rezeptoren und hemmen die Bildung entzündungsfördernder Botenstoffe. Weil der Wirkstoff in der Haut rasch weiter abgebaut wird, ist das Risiko für Hautverdünnung im Vergleich zu anderen Kortisoncremes ähnlicher Stärke geringer.","nebenwirkungen":{"unbekannt":["Brennen, Juckreiz oder Reizung an der Auftragsstelle","Hautatrophie (Hautverdünnung), Teleangiektasien (erweiterte Äderchen), Dehnungsstreifen (Striae) bei längerer Anwendung","Steroidakne, periorale Dermatitis (Ausschlag um den Mund)","Hellere Hautstellen (Hypopigmentierung), vermehrte Behaarung","Allergische Kontaktdermatitis","Sekundäre Hautinfektionen","Verschwommenes Sehen (z. B. durch Chorioretinopathie)","Bei grossflächiger oder langer Anwendung: Unterdrückung der Nebennierenrinde"]},"schwangerschaft":"Nur nach ärztlicher Abwägung, kleinflächig und kurzzeitig; nicht grossflächig, nicht langfristig und nicht unter luftdichten Verbänden anwenden.","stillzeit":"Kleinflächige, kurzzeitige Anwendung nach ärztlicher Abwägung möglich; nicht im Brustbereich auftragen.","hinweise":["Dünn auftragen und nur so lange wie nötig anwenden; die Grundlage (Creme, Salbe, Fettsalbe) richtet sich nach dem Hautzustand.","Nicht in die Augen bringen; nach dem Auftragen die Hände waschen.","Keine luftdichten Verbände ohne ärztliche Anweisung.","Nach längerer Anwendung nicht abrupt absetzen, sondern schrittweise reduzieren."],"darreichung":["Creme","Salbe","Fettsalbe"]},"prednisolon":{"wirkmechanismus":"Dämpft Entzündungen und überschiessende Reaktionen des Immunsystems. Prednisolon ist ein synthetisches Glukokortikoid, das an den Glukokortikoid-Rezeptor im Zellinneren bindet und im Zellkern die Bildung entzündungsfördernder Botenstoffe (Zytokine, Prostaglandine, Leukotriene) unterdrückt sowie die Aktivität von Abwehrzellen hemmt. Es wirkt etwa 4-mal stärker entzündungshemmend als körpereigenes Cortisol und hat eine geringe salzzurückhaltende (mineralokortikoide) Wirkung. Prednisolon ist zugleich der wirksame Stoff, in den Prednison in der Leber umgewandelt wird.","nebenwirkungen":{"unbekannt":["Erhöhte Infektanfälligkeit und Verschleierung von Infektionen","Erhöhter Blutzucker bis zum Steroiddiabetes","Cushing-Syndrom (Vollmondgesicht, Stammfettsucht), Gewichtszunahme","Osteoporose, Knochennekrose (z. B. Hüftkopf), Muskelschwäche, Sehnenriss","Magen-Darm-Geschwüre und -Blutungen, Pankreatitis","Psychische Störungen (Schlaflosigkeit, Euphorie, Unruhe, Depression, Psychose)","Bluthochdruck, Wassereinlagerungen, Kaliummangel","Nebennierenrindeninsuffizienz nach dem Absetzen, Wachstumshemmung bei Kindern","Dünne Haut, Akne, verzögerte Wundheilung; grauer und grüner Star bei längerer Anwendung","Augentropfen: Brennen, verschwommenes Sehen, erhöhter Augeninnendruck, verzögerte Heilung von Hornhautverletzungen"]},"schwangerschaft":"Nur nach ärztlicher Abwägung. Prednisolon wird in der Plazenta zu einem grossen Teil abgebaut; bei längerer Behandlung sind dennoch Wachstumsverzögerung und eine Unterfunktion der Nebennieren beim Neugeborenen möglich.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; bei üblichen Dosen ist Stillen meist möglich. Bei hohen Dosen ärztlich abklären; ein Abstand von einigen Stunden zwischen Einnahme und Stillen vermindert die Menge in der Milch.","hinweise":["Tabletten morgens mit dem Frühstück einnehmen (weniger Magenbeschwerden und Schlafstörungen).","Nach längerer Behandlung nicht abrupt absetzen, sondern nach ärztlichem Schema ausschleichen (Gefahr einer Nebennierenkrise).","Bei längerer Einnahme Blutzucker, Blutdruck, Augeninnendruck und Knochengesundheit kontrollieren lassen; auf ausreichend Calcium und Vitamin D achten.","Augentropfen (Suspension) vor Gebrauch gut schütteln; nur unter augenärztlicher Kontrolle anwenden."],"darreichung":["Tabletten","Augentropfen (Suspension)","Augensalbe"]},"prednison":{"wirkmechanismus":"Dämpft Entzündungen und überschiessende Reaktionen des Immunsystems. Prednison ist eine Vorstufe (Prodrug) und wird in der Leber rasch in den eigentlichen Wirkstoff Prednisolon umgewandelt. Prednisolon bindet an den Glukokortikoid-Rezeptor im Zellinneren und unterdrückt im Zellkern die Bildung entzündungsfördernder Botenstoffe (Zytokine, Prostaglandine, Leukotriene) sowie die Aktivität von Abwehrzellen. Es wirkt etwa 4-mal stärker entzündungshemmend als körpereigenes Cortisol und hat eine geringe salzzurückhaltende Wirkung. Die Form mit verzögerter Freisetzung gibt den Wirkstoff erst rund 4 Stunden nach der Einnahme frei, also in der Nacht, wenn die entzündlichen Botenstoffe ansteigen.","nebenwirkungen":{"unbekannt":["Erhöhte Infektanfälligkeit und Verschleierung von Infektionen","Erhöhter Blutzucker bis zum Steroiddiabetes","Cushing-Syndrom (Vollmondgesicht, Stammfettsucht), Gewichtszunahme","Osteoporose, Knochennekrose (z. B. Hüftkopf), Muskelschwäche, Sehnenriss","Magen-Darm-Geschwüre und -Blutungen, Pankreatitis","Psychische Störungen (Schlaflosigkeit, Euphorie, Unruhe, Depression, Psychose)","Bluthochdruck, Wassereinlagerungen, Kaliummangel","Nebennierenrindeninsuffizienz nach dem Absetzen, Wachstumshemmung bei Kindern","Dünne Haut, Akne, verzögerte Wundheilung; grauer und grüner Star bei längerer Anwendung"]},"schwangerschaft":"Nur nach ärztlicher Abwägung. Der Wirkstoff wird in der Plazenta zu einem grossen Teil abgebaut; bei längerer Behandlung sind dennoch Wachstumsverzögerung und eine Unterfunktion der Nebennieren beim Neugeborenen möglich.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; bei üblichen Dosen ist Stillen meist möglich. Bei hohen Dosen ärztlich abklären; ein Abstand von einigen Stunden zwischen Einnahme und Stillen vermindert die Menge in der Milch.","hinweise":["Normale Tabletten morgens mit dem Frühstück einnehmen; Tabletten mit verzögerter Freisetzung (Lodotra) abends mit oder nach dem Abendessen unzerkaut schlucken.","Nach längerer Behandlung nicht abrupt absetzen, sondern nach ärztlichem Schema ausschleichen (Gefahr einer Nebennierenkrise).","Bei längerer Einnahme Blutzucker, Blutdruck, Augeninnendruck und Knochengesundheit kontrollieren lassen; auf ausreichend Calcium und Vitamin D achten.","Bei Fieber, Infektzeichen oder vor Operationen die Kortison-Einnahme angeben."],"darreichung":["Tabletten","Tabletten mit verzögerter Wirkstofffreisetzung"]},"pregabalin":{"wirkmechanismus":"Dämpft die übermässige Aktivität von Nervenzellen und lindert so Nervenschmerzen, Angst und Krampfanfälle. Pregabalin bindet an die Alpha-2-Delta-Untereinheit spannungsabhängiger Calciumkanäle und vermindert dadurch die Freisetzung erregender Botenstoffe wie Glutamat, Noradrenalin und Substanz P. Es wird praktisch nicht verstoffwechselt und unverändert über die Nieren ausgeschieden.","nebenwirkungen":{"sehrHaeufig":["Schwindel, Schläfrigkeit","Kopfschmerzen"],"haeufig":["Nasen-Rachen-Entzündung, gesteigerter Appetit, Gewichtszunahme","Euphorie, Verwirrtheit, Reizbarkeit, Desorientierung, Schlaflosigkeit, verminderte Libido","Gang- und Koordinationsstörungen, Zittern, Sprechstörungen, Gedächtnis- und Aufmerksamkeitsstörungen, Kribbeln","Verschwommenes Sehen, Doppelbilder, Drehschwindel","Übelkeit, Erbrechen, Verstopfung, Durchfall, Blähungen, Mundtrockenheit","Muskelkrämpfe, Gelenk- und Rückenschmerzen","Erektionsstörungen","Wassereinlagerungen (Ödeme), Stürze, Müdigkeit"],"gelegentlich":["Überempfindlichkeitsreaktionen","Hypoglykämie (Unterzuckerung)","Halluzinationen, Panikattacken, Depression","Ohnmacht, Muskelzuckungen (Myoklonien)","Herzrasen, AV-Block 1. Grades, Blutdruckveränderungen","Atemnot, Nasenbluten","Hautausschlag, Nesselsucht, Schwitzen","Schmerzen beim Wasserlassen, Harninkontinenz"],"selten":["Angioödem (Schwellung von Gesicht, Zunge, Rachen)","Neutropenie (Mangel an weissen Blutkörperchen)","Krampfanfälle, Bewusstlosigkeit","QT-Verlängerung, Herzinsuffizienz","Lungenödem","Pankreatitis","Stevens-Johnson-Syndrom","Rhabdomyolyse (Muskelzerfall), Nierenversagen"],"sehrSelten":["Leberversagen, Hepatitis"],"unbekannt":["Abhängigkeit, Entzugssymptome nach dem Absetzen","Suizidgedanken","Atemdepression"]},"schwangerschaft":"Nicht anwenden, ausser bei eindeutiger Notwendigkeit nach ärztlicher Abwägung; Hinweise auf ein leicht erhöhtes Fehlbildungsrisiko. Frauen im gebärfähigen Alter sollen wirksam verhüten.","stillzeit":"Geht in die Muttermilch über; Stillen wird während der Behandlung nicht empfohlen.","hinweise":["Nicht abrupt absetzen, sondern über mindestens eine Woche ausschleichen (Entzugssymptome wie Schlaflosigkeit, Übelkeit, Angst).","Alkohol meiden; Fahrtüchtigkeit ist besonders zu Beginn eingeschränkt.","Bei Atemproblemen, starker Schläfrigkeit, Schwellungen im Gesicht oder Sehstörungen ärztlich melden.","Nur wie verordnet einnehmen – Pregabalin kann missbraucht werden und abhängig machen."],"darreichung":["Kapseln"]},"progesteron":{"wirkmechanismus":"Ersetzt das körpereigene Gelbkörperhormon, das die Gebärmutterschleimhaut auf die Einnistung eines Embryos vorbereitet und eine frühe Schwangerschaft erhält. Progesteron bindet an Progesteronrezeptoren und wandelt die durch Östrogen aufgebaute Schleimhaut in eine sekretorische Schleimhaut um. Bei Hormonersatz verhindert es so ein übermässiges Wachstum der Gebärmutterschleimhaut unter Östrogen. Einige Abbauprodukte wirken beruhigend auf das Gehirn (über GABA-A-Rezeptoren), was Müdigkeit und Schwindel nach der Einnahme erklärt.","nebenwirkungen":{"haeufig":["Zyklusveränderungen, Ausbleiben der Regel oder Zwischenblutungen","Kopfschmerzen"],"gelegentlich":["Schläfrigkeit, vorübergehende Benommenheit und Schwindel (vor allem nach Einnahme)","Brustspannen oder Brustschmerzen","Erbrechen, Durchfall, Verstopfung","Juckreiz, Akne","Cholestatische Gelbsucht (Gallenstau)"],"selten":["Übelkeit"],"sehrSelten":["Depression","Nesselsucht (Urtikaria)","Chloasma (bräunliche Pigmentflecken im Gesicht)"],"unbekannt":["Lokale Reizung, Juckreiz oder Ausfluss bei vaginaler Anwendung","Thromboembolische Ereignisse (Thrombose, Lungenembolie)","Schmerzen oder Rötung an der Einstichstelle (Injektion)"]},"schwangerschaft":"Zur Unterstützung der Frühschwangerschaft im Rahmen einer Kinderwunschbehandlung zugelassen; ein schädigender Einfluss auf das Kind ist nicht bekannt. Ausserhalb dieser Indikation keine Anwendung in der Schwangerschaft.","stillzeit":"Progesteron geht in die Muttermilch über; eine Anwendung in der Stillzeit wird nicht empfohlen.","hinweise":["Kapseln zum Einnehmen abends beim Zubettgehen und nicht zusammen mit einer Mahlzeit einnehmen – sie können müde und schwindlig machen.","Bei Müdigkeit oder Schwindel kein Fahrzeug lenken und keine Maschinen bedienen.","Bei vaginaler Anwendung Kapsel bzw. Gel tief in die Scheide einführen.","Bei Zeichen einer Thrombose (geschwollenes, schmerzhaftes Bein, Atemnot), Sehstörungen oder Gelbsucht sofort ärztlichen Rat einholen."],"darreichung":["Weichkapseln (zum Einnehmen oder zur vaginalen Anwendung)","Vaginalgel","Injektionslösung (subkutan)"]},"propafenon":{"wirkmechanismus":"Stabilisiert den Herzrhythmus, indem es die Erregungsleitung im Herzen verlangsamt. Propafenon blockiert als Antiarrhythmikum der Klasse IC die schnellen Natriumkanäle der Herzmuskelzellen; Leitungsgeschwindigkeit und Erregbarkeit nehmen ab (verlängerte PQ- und QRS-Zeit). Zusätzlich wirkt es schwach betablockierend und calciumantagonistisch. Abgebaut wird es vor allem über CYP2D6 zum ebenfalls wirksamen 5-Hydroxypropafenon; bei langsamen CYP2D6-Metabolisierern sind die Spiegel höher.","nebenwirkungen":{"sehrHaeufig":["Schwindel","Erregungsleitungsstörungen des Herzens (z. B. AV-Block, Schenkelblock)","Herzklopfen (Palpitationen)"],"haeufig":["Kopfschmerzen, Geschmacksstörungen","Verschwommenes Sehen","Angst, Schlafstörungen","Langsamer oder schneller Puls, Vorhofflattern","Atemnot (Dyspnoe)","Übelkeit, Erbrechen, Bauchschmerzen, Durchfall, Verstopfung, Mundtrockenheit","Leberfunktionsstörungen","Müdigkeit, Schwäche, Brustschmerzen, Fieber"],"gelegentlich":["Thrombozytopenie (Mangel an Blutplättchen)","Kammertachykardie und andere neue Rhythmusstörungen (proarrhythmische Wirkung)","Hypotonie (tiefer Blutdruck), Ohnmacht (Synkope)","Kribbeln (Parästhesien), Gangunsicherheit","Hautausschlag, Juckreiz","Erektionsstörungen","Appetitlosigkeit, Albträume, Blähungen"],"unbekannt":["Agranulozytose (gefährlicher Mangel an weissen Blutkörperchen)","Kammerflimmern","Verschlechterung einer Herzinsuffizienz","Krampfanfälle, Verwirrtheit","Cholestatische Hepatitis, Gelbsucht","Lupus-ähnliches Syndrom","Verminderte Spermienzahl (rückbildungsfähig)"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; Propafenon gelangt zum Ungeborenen. Nur anwenden, wenn der Nutzen das Risiko klar überwiegt.","stillzeit":"Geht in die Muttermilch über; Anwendung nur nach ärztlicher Abwägung und mit Beobachtung des Säuglings.","hinweise":["Tabletten unzerkaut mit Flüssigkeit nach dem Essen einnehmen (bitterer Geschmack, betäubende Wirkung im Mund).","Regelmässige EKG-Kontrollen; bei Ohnmacht, Herzrasen oder Atemnot sofort ärztliche Hilfe holen.","Schwindel und Sehstörungen können die Fahrtüchtigkeit beeinträchtigen.","Bei Fieber, Halsschmerzen oder anderen Infektzeichen Blutbild kontrollieren lassen (Agranulozytose möglich)."],"darreichung":["Filmtabletten"]},"propofol":{"wirkmechanismus":"Lässt innerhalb von Sekunden einschlafen; nach Ende der Zufuhr wacht man rasch und meist klar wieder auf. Propofol verstärkt im Gehirn die hemmende Wirkung des Botenstoffs GABA am GABA-A-Rezeptor. Es wirkt nicht schmerzlindernd und wird deshalb bei Operationen mit Schmerzmitteln kombiniert. Der Abbau erfolgt sehr rasch in der Leber und zusätzlich ausserhalb der Leber.","nebenwirkungen":{"sehrHaeufig":["Schmerzen an der Injektionsstelle"],"haeufig":["Kopfschmerzen beim Aufwachen","Bradykardie (langsamer Puls)","Hypotonie (Blutdruckabfall)","Kurzer Atemstillstand bei der Einleitung","Übelkeit und Erbrechen beim Aufwachen"],"gelegentlich":["Thrombose und Venenentzündung an der Injektionsstelle"],"selten":["Krampfanfall-ähnliche Bewegungen, Muskelzuckungen"],"sehrSelten":["Anaphylaxie (schwere allergische Reaktion)","Lungenödem","Pankreatitis (Bauchspeicheldrüsenentzündung)","Verfärbung des Urins bei langer Anwendung","Sexuelle Enthemmung","Fieber nach der Operation"],"unbekannt":["Propofol-Infusionssyndrom (Übersäuerung, Muskelzerfall, Herz- und Nierenversagen) bei hohen Dosen über lange Zeit","Hyperkaliämie, erhöhte Blutfette","Herzrhythmusstörungen, Herzversagen","Euphorie, Missbrauch und Abhängigkeit","Hepatitis","Priapismus (schmerzhafte Dauererektion)"]},"schwangerschaft":"Nur wenn eindeutig erforderlich. Propofol passiert die Plazenta und kann beim Neugeborenen dämpfend wirken; hohe Dosen beim Kaiserschnitt vermeiden.","stillzeit":"Geringe Mengen gehen in die Muttermilch über. Laut Fachinformation 24 Stunden nach der Anwendung nicht stillen und die in dieser Zeit gebildete Milch verwerfen.","hinweise":["Nach Narkose oder Sedierung mindestens 24 Stunden nicht Auto fahren und nicht allein nach Hause gehen; kein Alkohol.","Eine Soja- oder Erdnussallergie vor der Anwendung melden.","Wird nur von in Anästhesie oder Intensivmedizin geschultem Personal unter Überwachung von Atmung und Kreislauf angewendet."],"darreichung":["Emulsion zur Injektion oder Infusion"]},"propranolol":{"wirkmechanismus":"Senkt Puls und Blutdruck, indem es die Wirkung der Stresshormone Adrenalin und Noradrenalin am Herzen und an den Gefässen abschwächt. Propranolol blockiert ohne Unterschied die Beta-1-Rezeptoren (Herz, Niere) und die Beta-2-Rezeptoren (Bronchien, Gefässe, Leber). Dadurch schlägt das Herz langsamer und weniger kräftig, braucht weniger Sauerstoff, und die Freisetzung von Renin aus der Niere sinkt. Die Blockade der Beta-2-Rezeptoren kann die Atemwege verengen und die Erholung aus einer Unterzuckerung verzögern. Bei infantilen Hämangiomen wirkt es unter anderem über eine Gefässverengung und eine Hemmung des Gefässwachstums.","nebenwirkungen":{"sehrHaeufig":["Bei Säuglingen (Hemangiol): Schlafstörungen, Bronchitis, Durchfall, Erbrechen"],"haeufig":["Müdigkeit, Erschöpfung","Bradykardie (langsamer Puls)","Kalte Hände und Füsse, Raynaud-Syndrom","Schlafstörungen, Albträume"],"gelegentlich":["Magen-Darm-Beschwerden wie Übelkeit, Erbrechen, Durchfall"],"selten":["Verschlechterung einer Herzinsuffizienz, AV-Block","Blutdruckabfall beim Aufstehen, Ohnmacht","Bronchospasmus (Verkrampfung der Atemwege), besonders bei Asthma","Schwindel, Verwirrtheit, Stimmungsschwankungen, Halluzinationen, Psychosen","Thrombozytopenie (Mangel an Blutplättchen), Purpura","Haarausfall, psoriasisartige Hautreaktionen, Verschlechterung einer Psoriasis","Sehstörungen, trockene Augen","Kribbeln (Parästhesien), Verschlechterung einer Schaufensterkrankheit"],"sehrSelten":["Auslösung oder Verschlechterung einer Myasthenia gravis"],"unbekannt":["Hypoglykämie (Unterzuckerung), besonders bei Kindern und nach Fasten, selten mit Krampfanfällen","Depression","Bindehautentzündung"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung: Propranolol kann das Wachstum des Kindes vermindern und beim Neugeborenen langsamen Puls, Unterzuckerung und Atemprobleme verursachen; Neugeborene in den ersten Lebenstagen überwachen.","stillzeit":"Geht in die Muttermilch über; laut Fachinformation wird Stillen nicht empfohlen. Wird dennoch gestillt, den Säugling auf langsamen Puls und Unterzuckerung beobachten.","hinweise":["Nicht abrupt absetzen, sondern schrittweise über 1–2 Wochen ausschleichen (Gefahr von Angina-pectoris-Anfällen, Herzinfarkt oder Blutdruckanstieg).","Kann die Reaktionsfähigkeit beeinträchtigen, besonders zu Beginn und zusammen mit Alkohol.","Diabetes: Unterzuckerungen können ohne Herzklopfen und Zittern verlaufen – Blutzucker häufiger messen.","Hemangiol: während oder direkt nach einer Mahlzeit geben; bei Nahrungsverweigerung, Erbrechen oder einem Atemwegsinfekt mit Atemnot die Gabe aussetzen und ärztlichen Rat einholen."],"darreichung":["Tabletten","Lösung zum Einnehmen"]},"prothrombinkomplex-ppsb":{"wirkmechanismus":"Ersetzt fehlende Gerinnungsfaktoren und bringt die Blutgerinnung innert Minuten wieder in Gang. PPSB ist ein aus menschlichem Spenderplasma gewonnenes Konzentrat der Vitamin-K-abhängigen Gerinnungsfaktoren II (Prothrombin), VII, IX und X sowie der gerinnungshemmenden Proteine C und S. Nach der Infusion normalisieren sich INR bzw. Quick-Wert rasch. Weil die zugeführten Faktoren nur eine begrenzte Zeit wirken, wird bei Vitamin-K-Antagonisten zusätzlich Vitamin K gegeben.","nebenwirkungen":{"haeufig":["Thromboembolische Ereignisse (Thrombosen, Embolien)","Kopfschmerzen"],"unbekannt":["Überempfindlichkeitsreaktionen bis anaphylaktischer Schock","Verbrauchskoagulopathie (disseminierte intravasale Gerinnung)","Heparininduzierte Thrombozytopenie (HIT)","Bildung von Antikörpern gegen einzelne Gerinnungsfaktoren","Fieber"]},"schwangerschaft":"Keine kontrollierten Erfahrungen; nur bei eindeutiger Notwendigkeit anwenden.","stillzeit":"Keine Daten; nur bei eindeutiger Notwendigkeit anwenden.","hinweise":["Wird im Spital als langsame intravenöse Injektion gegeben; bei Vitamin-K-Antagonisten wird zusätzlich Vitamin K verabreicht.","Nach der Gabe auf Zeichen einer Thrombose (Beinschwellung, Brustschmerz, Atemnot) oder einer allergischen Reaktion achten.","Bei regelmässiger Behandlung mit Plasmapräparaten werden Impfungen gegen Hepatitis A und B empfohlen."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektionslösung"]},"prucaloprid":{"wirkmechanismus":"Regt die natürliche Darmbewegung an. Prucaloprid aktiviert selektiv und mit hoher Affinität Serotonin-5-HT4-Rezeptoren im Nervensystem der Darmwand. Dadurch werden die vorwärtstreibenden (propulsiven) Kontraktionen des Dickdarms verstärkt und die Darmpassage beschleunigt.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Übelkeit","Durchfall","Bauchschmerzen"],"haeufig":["Verminderter Appetit","Schwindel","Erbrechen","Dyspepsie (Verdauungsbeschwerden)","Blähungen","Abnorme Darmgeräusche","Häufiges Wasserlassen (Pollakisurie)","Müdigkeit"],"gelegentlich":["Zittern (Tremor)","Herzklopfen (Palpitationen)","Blutung aus dem Enddarm","Fieber","Unwohlsein"]},"schwangerschaft":"Nicht empfohlen; Frauen im gebärfähigen Alter sollen während der Behandlung zuverlässig verhüten.","stillzeit":"Prucaloprid geht in die Muttermilch über; während der Stillzeit nicht anwenden.","hinweise":["Einmal täglich, unabhängig von den Mahlzeiten, zu einer beliebigen Tageszeit einnehmen.","Kopfschmerzen und Magen-Darm-Beschwerden treten meist am ersten Behandlungstag auf und klingen in der Regel rasch ab.","Tritt nach 4 Wochen keine Besserung ein, die Behandlung ärztlich überprüfen lassen.","Schwindel und Müdigkeit können die Fahrtüchtigkeit beeinträchtigen."],"darreichung":["Filmtabletten"]},"pyrantel":{"wirkmechanismus":"Lähmt die Würmer, die dann mit dem Stuhl ausgeschieden werden. Pyrantel wirkt an den nikotinischen Acetylcholinrezeptoren der Wurmmuskulatur als depolarisierender Blocker und löst eine spastische Lähmung aus. Aus dem Darm wird es nur in geringen Mengen aufgenommen, deshalb sind Nebenwirkungen im übrigen Körper selten.","nebenwirkungen":{"unbekannt":["Magen-Darm-Beschwerden (Appetitlosigkeit, Übelkeit, Erbrechen, Bauchkrämpfe, Durchfall)","Kopfschmerzen, Schwindel, Schläfrigkeit oder Schlaflosigkeit","Hautausschlag und andere Überempfindlichkeitsreaktionen","Vorübergehend erhöhte Leberwerte"]},"schwangerschaft":"Die Erfahrungen sind begrenzt. Im ersten Schwangerschaftsdrittel nicht und danach nur nach ärztlicher Abwägung anwenden.","stillzeit":"Es ist nicht bekannt, ob Pyrantel in die Muttermilch übergeht; nur nach ärztlicher Rücksprache anwenden.","hinweise":["Einmalige Einnahme unabhängig von den Mahlzeiten; Fasten oder Abführmittel sind nicht nötig. Suspension vor Gebrauch schütteln.","Alle Familienmitglieder mitbehandeln und die Behandlung nach 2–3 Wochen wiederholen.","Hygiene: Hände waschen, Fingernägel kurz halten, Unterwäsche und Bettwäsche heiss waschen."],"darreichung":["Kautabletten","Suspension zum Einnehmen"]},"pyridoxin-vitamin-b6":{"wirkmechanismus":"Vitamin B6 wird für den Eiweiss- und Aminosäurestoffwechsel, die Blutbildung und die Bildung von Botenstoffen im Nervensystem benötigt. Pyridoxin wird im Körper zu Pyridoxal-5'-phosphat umgewandelt, dem Coenzym von über 100 Enzymen, u. a. von Transaminasen und Decarboxylasen (z. B. bei der Bildung von Serotonin, Dopamin und GABA). Bestimmte Arzneimittel wie Isoniazid binden oder hemmen Vitamin B6 und können so einen Mangel auslösen.","nebenwirkungen":{"unbekannt":["Periphere sensorische Neuropathie (Kribbeln, Taubheit, Gangunsicherheit) bei langdauernder Einnahme hoher Dosen","Überempfindlichkeitsreaktionen der Haut","Magen-Darm-Beschwerden (Übelkeit)"]},"schwangerschaft":"Dosen im Bereich des Tagesbedarfs sind unbedenklich. Hohe Dosen nur nach ärztlicher Abwägung.","stillzeit":"Geht in die Muttermilch über; übliche Dosen sind unbedenklich. Sehr hohe Dosen können die Milchbildung hemmen und sollen vermieden werden.","hinweise":["Hohe Dosen nicht über längere Zeit ohne ärztliche Kontrolle einnehmen; bei Kribbeln oder Taubheit in Händen oder Füssen absetzen und ärztlich abklären lassen.","Auf weitere Vitamin-B6-haltige Präparate (z. B. Vitamin-B-Komplex, Magnesiumpräparate mit B6) achten, um eine Überdosierung zu vermeiden."],"darreichung":["Tabletten"]}});
